Object.assign(window.TEM8_DICTIONARY, {"needle":{"oxford":{"phon":"ˈniːdl","pos":"noun","senses":[{"en":"a small thin piece of steel that you use for sewing, with a point at one end and a hole for the thread at the other","cn":"针；缝衣针","sc":"for sewing","ex":{"en":"a needle and thread","cn":"针线"}},{"en":"a long thin piece of plastic or metal with a point at one end that you use for knitting. You usually use two together.","cn":"编织针","sc":"for knitting","ex":{"en":"Vera's knitting needles clicked away.","cn":"维拉的织针发出咔哒声。"}},{"en":"a very thin, pointed piece of steel used on the end of a syringe for putting a drug into somebody’s body, or for taking blood out of it","cn":"注射针；针头","sc":"for drugs","ex":{"en":"a hypodermic needle","cn":"皮下注射器针头"}},{"en":"a thin piece of metal on a scientific instrument that moves to point to the correct measurement or direction","cn":"指针","sc":"on instrument","ex":{"en":"The compass needle was pointing north.","cn":"罗盘指针指向北方。"}},{"en":"the thin, hard, pointed leaf of a pine tree","cn":"针叶；松针","g":"[usually plural]","sc":"on pine tree","ex":{"en":"A soft blanket of pine needles covered the forest floor.","cn":"森林的地面上覆盖着一层柔软的松针毯。"}},{"en":"the very small pointed piece of metal that touches a record that is being played in order to produce the sound","cn":"唱针；磁针","sc":"on record player","ex":{"en":"She lowered the needle onto the record.","cn":"她把唱针放到唱片上。"}},{"en":"to deliberately annoy somebody, especially by criticizing them continuously","cn":"刺激；故意招惹；（尤指）不断地数落","ex":{"en":"Don't let her needle you.","cn":"别让她数落你。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"缝衣针;针","en":"A needle is a small, very thin piece of polished metal which is used for sewing. It has a sharp point at one end and a hole in the other for a thread to go through."},{"pos":"N-COUNT 可数名词","cn":"编织针;棒针","en":"Knitting needles are thin sticks that are used for knitting. They are usually made of plastic or metal and have a point at one end."},{"pos":"N-COUNT 可数名词","cn":"注射针;针头","en":"A needle is a thin hollow metal rod with a sharp point, which is part of a medical instrument called a syringe. It is used to put a drug into someone's body, or to take blood out."},{"pos":"N-COUNT 可数名词","cn":"(针灸疗法用的)银针，金针","en":"A needle is a thin metal rod with a point which is put into a patient's body during acupuncture."},{"pos":"N-COUNT 可数名词","cn":"(唱机的)唱针","en":"On a record player, the needle is the small pointed device that touches the record and picks up the sound signals.","ex":{"en":"She took the needle off the record and turned the lights out.","cn":"她把唱针从唱片上移开，把灯也关了。"}},{"pos":"N-COUNT 可数名词","cn":"(仪表上的)指针","en":"On an instrument which measures something such as speed or weight, the needle is the long strip of metal or plastic on the dial that moves backwards and forwards, showing the measurement.","ex":{"en":"She kept looking at the dial on the boiler. The needle had reached 250 degrees.","cn":"她一直看着锅炉上的刻度盘，指针已指向了250度。"}},{"pos":"N-COUNT 可数名词","cn":"(杉树、松树等的)针叶","en":"The needles of a fir or pine tree are its thin, hard, pointed leaves.","ex":{"en":"The carpet of pine needles was soft underfoot.","cn":"脚下厚厚的松针踩上去软绵绵的。"}},{"pos":"VERB 动词","cn":"刺激;惹…发火;(尤指)不断数落","en":"If someone needles you, they annoy you continually, especially by criticizing you.","ex":{"en":"Blake could see he had needled Jerrold, which might be unwise.","cn":"布莱克看得出他已经惹怒了杰罗尔德，这也许并不是什么明智之举。"}},{"pos":"See also:","cn":"","en":"like looking for a needle in a haystack→see: ;"}]},"media":{"uk":"media/uk/needle__gb_1.mp3","us":"media/us/needle__us_1.mp3","img":["media/ldoce/img/needles.jpg"]},"examples":[{"en":"Searching for one man in this city is like looking for a needle in a haystack.","cn":"在这个城市里找一个人无异于大海捞针。"},{"en":"The compass needle was pointing north.","cn":"罗盘指针指向北方。"}]},"nes":{"oxford":{"phon":"","pos":"abbr.","senses":[{"en":"north-east; north-eastern","cn":"东北方（的）；东北部（的）"}]}},"never":{"media":{"uk":"media/uk/never__gb_1.mp3","us":"media/us/never__us_1.mp3"},"oxford":{"phon":"ˈnevə(r)","pos":"adverb","senses":[{"en":"not at any time; not on any occasion","cn":"从不；绝不；从未；未曾","ex":{"en":"You never help me.","cn":"你从不帮我。"}},{"en":"used to emphasize a negative statement instead of ‘not’","cn":"（与 not 同义，语气较强）一点都不，从未","lab":"especially British English","ex":{"en":"I never knew (= didn't know until now) you had a twin sister.","cn":"我从来不知道你还有个双胞胎姐姐。"}},{"en":"used to show that you are very surprised about something because you do not believe it is possible","cn":"（表示惊讶，因为觉得不可能）不会吧","ex":{"en":"‘I got the job.’ ‘Never!’","cn":"“我得到那份工作了。”“不可能吧！”"},"pos":"exclamation"}]},"collins":{"senses":[{"pos":"ADV-NEG 否定副词","cn":"从不;永不","en":"Never means at no time in the past or at no time in the future.","ex":{"en":"I have never lost the weight I put on in my teens","cn":"我十几岁时增加的体重一直没有减下去。"}},{"pos":"ADV-NEG 否定副词","cn":"决不;千万不","en":"Never means 'not in any circumstances at all'.","ex":{"en":"I would never do anything to hurt him","cn":"我决不会做任何伤害他的事情。"}},{"pos":"PHRASE 短语","cn":"永不，永无，从未(never的强调说法)","en":"Never ever is an emphatic way of saying 'never'.","ex":{"en":"I never, ever sit around thinking, 'What shall I do next?'","cn":"我从不闲坐着琢磨：“我接下来做什么呢？”"}},{"pos":"ADV-NEG 否定副词","cn":"(指过去)不，没有","en":"Never is used to refer to the past and means 'not'.","ex":{"en":"He never achieved anything","cn":"他从没有取得任何成就。"}},{"pos":"EXCLAM 感叹语","cn":"(表示惊讶)不会!不可能!","en":"You say 'never!' to indicate how surprised or shocked you are by something that someone has just said."},{"pos":"EXCLAM 感叹语","cn":"(表示惊讶)我真没看到(或发现、想到)过","en":"You say 'Well, I never' to indicate that you are very surprised about something that you have just seen or found out.","ex":{"en":"'What were you up to there?' — 'I was head of the information department.' — 'Well I never!'","cn":"“你在那儿干什么？”——“我是信息部的负责人。”——“啊，真没想到!”"}},{"pos":"PHRASE 短语","cn":"(经常为幽默地表示)不好，不行，不合适","en":"If you say that something will never do or would never do, you are saying, often humorously, that you think it is not appropriate or not suitable in some way.","ex":{"en":"It would never do to have Henry there in her apartment","cn":"亨利呆在她的公寓里怎么也不合适。"}},{"pos":"","cn":"","en":"never fear→see: ; never mind→see: ;"}]},"examples":[{"en":"‘I work for a company called Orion Technology.’ ‘Never heard of them.’ “","cn":"我在一家名为奥里昂科技的公司工作。” “从来没听说过。”"},{"en":"( especially BrE ) ‘I told my boss exactly what I thought of her.’ ‘You never did!’ (= ‘Surely you didn't!’) “","cn":"我对老板说了我对她的真实看法。” “不可能！”"}]},"necessities":{"oxford":{"phon":"nəˈsesəti","pos":"noun","senses":[{"en":"the fact that sth must happen or be done; the need for sth","cn":"必然；必要；需要"},{"en":"a thing that you must have and cannot manage without","cn":"必需的事物；必需品"}]},"media":{"uk":"media/uk/necessity__gb_1.mp3","us":"media/us/necessity__us_1.mp3"}},"negatives":{"oxford":{"phon":"ˈneɡətɪv","pos":"adjective","senses":[{"en":"bad or harmful","cn":"坏的；有害的"},{"en":"considering only the bad side of sth/sb; lacking enthusiasm or hope","cn":"消极的；负面的；缺乏热情的"}]},"media":{"uk":"media/uk/negative__gb_1.mp3","us":"media/us/negative__us_1.mp3"}},"newspaper":{"media":{"uk":"media/uk/newspaper__gb_1.mp3","us":"media/us/newspaper__us_1.mp3","img":["media/ldoce/img/newspaper.jpg"]},"oxford":{"phon":"ˈnjuːzpeɪpə(r)","pos":"noun","senses":[{"en":"a set of large printed sheets of paper, or a website, containing news, articles, advertisements, etc. and published every day or every week; the organization responsible for producing this","cn":"报纸；报社","g":"[countable]","ex":{"en":"a daily/weekly newspaper","cn":"日报；周报"}},{"en":"paper taken from old newspapers","cn":"旧报纸","g":"[uncountable]","ex":{"en":"Wrap all your glasses in newspaper.","cn":"把你的玻璃杯全用旧报纸包起来。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"报纸;报","en":"A newspaper is a publication consisting of a number of large sheets of folded paper, on which news, advertisements, and other information is printed.","ex":{"en":"He was carrying a newspaper","cn":"他拿着一份报纸。"}},{"pos":"N-COUNT 可数名词","cn":"报馆;报社","en":"A newspaper is an organization that produces a newspaper.","ex":{"en":"It is Britain's fastest growing national daily newspaper","cn":"这是英国发展最快的全国性日报社。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(尤指用作他途的)旧报纸","en":"Newspaper consists of pieces of old newspapers, especially when they are being used for another purpose such as wrapping things up.","ex":{"en":"He found two pots, each wrapped in newspaper.","cn":"他发现了两个分别用报纸包着的罐子。"}}]},"examples":[{"en":"Wrap all your glasses in newspaper.","cn":"把你的玻璃杯全用旧报纸包起来。"},{"en":"I read about it in the newspaper.","cn":"我在报上看到了这件事。"}]},"necessity":{"media":{"uk":"media/uk/necessity__gb_1.mp3","us":"media/us/necessity__us_1.mp3"},"oxford":{"phon":"nəˈsesəti","pos":"noun","senses":[{"en":"the fact that something must happen or be done; the need for something","cn":"必然；必要；需要","g":"[uncountable]","ex":{"en":"We recognize the necessity for a written agreement.","cn":"我们认为有必要签订一份书面协议。"}},{"en":"a thing that you must have and cannot manage without","cn":"必需的事物；必需品","g":"[countable]","ex":{"en":"Many people cannot even afford basic necessities such as food and clothing.","cn":"许多人甚至买不起食物和衣服之类的基本必需品。"}},{"en":"a situation that must happen and that cannot be avoided","cn":"必然性；不可避免的情况","g":"[countable, usually singular]","ex":{"en":"Living in London, he felt, was an unfortunate necessity.","cn":"他觉得在伦敦生活是迫于无奈。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"必然;必要","en":"The necessity of something is the fact that it must happen or exist.","ex":{"en":"There is agreement on the necessity of reforms","cn":"对改革的必要性已经达成了共识。"}},{"pos":"N-COUNT 可数名词","cn":"必需品;必不可少的事物","en":"A necessity is something that you must have in order to live properly or do something.","ex":{"en":"Water is a basic necessity of life.","cn":"生命离不开水。"}},{"pos":"N-COUNT 可数名词","cn":"不可避免的情况(或行动)","en":"A situation or action that is a necessity is necessary and cannot be avoided.","ex":{"en":"The President pleaded that strong rule from the centre was a regrettable, but temporary necessity.","cn":"总统辩解说，实行高度的中央集权虽不尽如人意，但暂时来说却是必要的。"}}]},"examples":[{"en":"Many people cannot even afford basic necessities such as food and clothing.","cn":"许多人甚至买不起食物和衣服之类的基本必需品。"},{"en":"This is, of necessity, a brief and incomplete account.","cn":"这必然是一个简略的、不完全的描述。"}]},"near":{"media":{"uk":"media/uk/near__gb_1.mp3","us":"media/us/near__us_1.mp3"},"oxford":{"phon":"nɪə(r)","pos":"preposition","senses":[{"en":"at a short distance away from somebody/something","cn":"在…附近；靠近","lab":"British English","ex":{"en":"Do you live near here?","cn":"你住在这附近吗？"}},{"en":"a short period of time from something","cn":"接近；临近","ex":{"en":"My birthday is very near Christmas.","cn":"我的生日离圣诞节很近。"}},{"en":"used before a number to mean ‘approximately’, ‘just below or above’","cn":"（用于数词前）大约，上下，接近","ex":{"en":"Share prices are near their record high of last year.","cn":"股票价格接近去年的最高纪录。"}},{"en":"similar to somebody/something in quality, size, etc.","cn":"（质量、大小等）相仿，接近","ex":{"en":"Nobody else comes near her in intellect.","cn":"谁也赶不上她聪明。"}},{"en":"close to a particular state","cn":"接近于（某种状态）；濒临；快要","ex":{"en":"a state near (to) death","cn":"濒死状态"}},{"en":"a short distance away","cn":"距离近；不远","lab":"British English","ex":{"en":"His house is very near.","cn":"他的房子就在附近。"},"pos":"adjective"},{"en":"a short time away in the future","cn":"不久以后","ex":{"en":"The conflict is unlikely to be resolved in the near future (= very soon).","cn":"冲突短期内不大可能解决。"},"pos":"adjective"},{"en":"coming next after somebody/something","cn":"随后；接近","ex":{"en":"She has a 12-point lead over her nearest rival.","cn":"她领先紧随其后的对手 12 分。"},"pos":"adjective"},{"en":"similar; most similar","cn":"近似；相似；不分伯仲","ex":{"en":"He was the nearest thing to (= the person most like) a father she had ever had.","cn":"她接触过的人中，他最像个父亲。"},"pos":"adjective"},{"en":"close to being somebody/something","cn":"接近的；差不多的","g":"[only before noun]","ex":{"en":"The election proved to be a near disaster for the party.","cn":"这次选举对该党来说几乎是一场灾难。"},"pos":"adjective"},{"en":"used to describe a close family connection","cn":"（亲属关系）近亲","g":"[only before noun]","ex":{"en":"Only the nearest relatives were present at the funeral.","cn":"只有几位近亲参加了葬礼。"},"pos":"adjective"},{"en":"at a short distance away","cn":"距离不远；在附近","ex":{"en":"A bomb exploded somewhere near.","cn":"一颗炸弹在附近爆炸。"},"pos":"adverb"},{"en":"a short time away in the future","cn":"不久以后","ex":{"en":"The exams are drawing near.","cn":"考试越来越近了。"},"pos":"adverb"},{"en":"almost","cn":"几乎；差不多","ex":{"en":"a near-perfect performance","cn":"近乎完美的表演"},"pos":"adverb"},{"en":"to come close to something in time or space","cn":"（时间或空间上）接近，靠近，临近","ex":{"en":"The project is nearing completion.","cn":"这项工程就要竣工了。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"PREP 介词","cn":"靠近;在…附近","en":"If something is near a place, thing, or person, it is a short distance from them.","ex":{"en":"Don't come near me","cn":"别靠近我。"}},{"pos":"PREP-PHRASE 短语介词","cn":"接近(某一状态);几乎;差不多","en":"If someone or something is near to a particular state, they have almost reached it.","ex":{"en":"After the war, The House of Hardie came near to bankruptcy","cn":"战后，哈迪家族濒于破产。"}},{"pos":"PREP-PHRASE 短语介词","cn":"近似于;和…差不多","en":"If something is similar to something else, you can say that it is near to it.","ex":{"en":"...a sickening sensation that was near to nausea.","cn":"近乎恶心的难受感觉"}},{"pos":"ADJ-SUPERL 形容词最高级形式","cn":"(与…)最相似的;(和…)几乎差不多的","en":"You describe the thing most similar to something as the nearest thing to it when there is no example of the thing itself.","ex":{"en":"It would appear that the legal profession is the nearest thing to a recession-proof industry","cn":"司法行业看来是最不易受经济萧条影响的领域了。"}},{"pos":"ADV-GRADED 副词","cn":"(时间或事件)临近，接近","en":"If a time or event draws near, it will happen soon.","ex":{"en":"The time for my departure from Japan was drawing nearer every day.","cn":"我离开日本的日子一天天近了。"}},{"pos":"PREP 介词","cn":"离(某一时间)不远;临近","en":"If something happens near a particular time, it happens just before or just after that time.","ex":{"en":"Performance is lowest between 3 a.m. and 5 a.m., and reaches a peak near midday","cn":"凌晨3点至5点表现最差，近中午时分最好。"}},{"pos":"PREP 介词","cn":"(指数量或数字)接近于，左右，上下","en":"You use near to say that something is a little more or less than an amount or number stated.","ex":{"en":"...to increase manufacturing from about 2.5 million cars a year to nearer 4.75 million","cn":"将轿车年产量从250万辆左右增加到接近475万辆"}},{"pos":"PREP 介词","cn":"往(见某人);去(到某处)","en":"You can say that someone will not go near a person or thing when you are emphasizing that they refuse to see them or go there.","ex":{"en":"He will absolutely not go near a hospital","cn":"他绝对不会去医院。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(两者中)距离较近的","en":"The near one of two things is the one that is closer.","ex":{"en":"...a mighty beech tree on the near side of the little clearing","cn":"矗立在林间小块空地近侧的一棵高大的山毛榉树"}},{"pos":"ADJ 形容词","cn":"近似的;差不多的","en":"You use near to indicate that something is almost the thing mentioned.","ex":{"en":"She was believed to have died in near poverty on the French Riviera.","cn":"据信她在法国里维埃拉去世时几乎身无分文。"}},{"pos":"ADJ-SUPERL 形容词最高级形式","cn":"(在竞赛中)实力接近的，旗鼓相当的","en":"In a contest, your nearest rival or challenger is the person or team that is most likely to defeat you.","ex":{"en":"He completed the lengthy course some three seconds faster than his nearest rival, Jonathon Ford","cn":"他比劲敌乔纳森·福特少用了大概3秒钟完成了漫长的赛程。"}},{"pos":"VERB 动词","cn":"靠近;走近","en":"When you near a place, you get quite near to it.","ex":{"en":"As he neared the stable, he slowed the horse and patted it on the neck","cn":"接近马厩时，他勒马缓行，轻拍它的脖颈。"}},{"pos":"VERB 动词","cn":"接近，临近(某一阶段或某一点)","en":"When someone or something nears a particular stage or point, they will soon reach that stage or point.","ex":{"en":"His age was hard to guess — he must have been nearing fifty","cn":"很难猜测他的年龄，他一定快50了。"}},{"pos":"VERB 动词","cn":"临近;即将来临","en":"You say that an important time or event nears when it is going to occur quite soon.","ex":{"en":"As half time neared, Hardyman almost scored twice","cn":"临近中场休息时，哈迪曼差点梅开二度。"}},{"pos":"PHRASE 短语","cn":"最亲近的人;最亲密的人;至亲","en":"People sometimes refer to their close relatives and friends as their nearest and dearest .","ex":{"en":"...that English convention of not showing your feelings, even to your nearest and dearest.","cn":"甚至不向最亲近的人流露自己情感的英国社会习俗"}},{"pos":"PHRASE 短语","cn":"远近;到处;四面八方","en":"You use near and far to indicate that you are referring to a very large area or distance.","ex":{"en":"People would gather from near and far","cn":"人们会从四面八方聚到一起。"}},{"pos":"PHRASE 短语","cn":"在不久的将来;在近期","en":"If you say that something will happen in the near future, you mean that it will happen quite soon.","ex":{"en":"The controversy regarding vitamin C is unlikely to be resolved in the near future.","cn":"关于维生素C的争议短期内不可能平息。"}},{"pos":"PHRASE 短语","cn":"一点儿也不;完全不;远不","en":"You use nowhere near and not anywhere near to emphasize that something is not the case.","ex":{"en":"They are nowhere near good enough","cn":"他们还远不够好。"}},{"pos":"PHRASE 短语","cn":"几乎丝毫不差地，几乎一样地(英国英语中亦作 as near as dammit)","en":"If you want to indicate that something is almost true, you can use the expressions near enough and damned near. In British English, you can also say as near as dammit.","ex":{"en":"I bought them for a pound apiece, near enough","cn":"我几乎是以一英镑一件的价钱买下了它们。"}},{"pos":"PHRASE 短语","cn":"差点，险些(发生某事)(英国英语中亦作 as near as dammit)","en":"If you want to indicate that something almost happened, you can use the expression damned near. In British English, you can also say as near as dammit .","ex":{"en":"He damned near fooled me","cn":"他险些把我骗了。"}}]},"examples":[{"en":"Profits fell from $11 million to nearer $8 million.","cn":"利润从 1 100 万元下跌到大约 800 万元。"},{"en":"There were about 3 000 people there, as near as I could judge.","cn":"据我判断，大约有 3 000 人在那里。"}]},"necessarily":{"media":{"uk":"media/uk/necessarily__gb_1.mp3","us":"media/us/necessarily__us_1.mp3"},"oxford":{"phon":"ˌnesəˈserəli","pos":"adverb","senses":[{"en":"used to say that something cannot be avoided","cn":"必然地；不可避免地","ex":{"en":"The number of places available is necessarily limited.","cn":"录取名额不可避免地很有限。"}}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"一定地;必要地","en":"If you say that something is not necessarily the case, you mean that it may not be the case or is not always the case.","ex":{"en":"Anger is not necessarily the most useful or acceptable reaction to such events","cn":"对于这种事，发火不见得是最有用或最能被接受的反应。"}},{"pos":"ADV 副词","cn":"不可避免地;必然地","en":"If you say that something necessarily happens or is the case, you mean that it has to happen or be the case and cannot be any different.","ex":{"en":"The most desirable properties necessarily command astonishingly high prices","cn":"最值得拥有的财产必然要价不菲。"}}]},"examples":[{"en":"The number of places available is necessarily limited.","cn":"可用场所的数量不可避免地很有限。"},{"en":"‘We're going to lose.’ ‘Not necessarily.’ “","cn":"我们会输的。” “未必。”"}]},"neural":{"oxford":{"phon":"ˈnjʊərəl","pos":"adjective","senses":[{"en":"connected with a nerve or the nervous system","cn":"神经的；神经系统的","ex":{"en":"neural processes","cn":"神经系统的作用"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"神经的;神经系统的","en":"Neural means relating to a nerve or to the nervous system.","ex":{"en":"...neural pathways in the brain.","cn":"大脑里的神经通路"}}]},"media":{"uk":"media/uk/neural__gb_1.mp3","us":"media/us/neural__us_1.mp3"},"examples":[{"en":"neural processes","cn":"神经系统的作用"},{"en":"signs of neural activity","cn":"神经活动的迹象"}]},"need":{"media":{"uk":"media/uk/need__gb_1.mp3","us":"media/us/need__us_1.mp3"},"oxford":{"phon":"niːd","pos":"verb","senses":[{"en":"to require something/somebody because they are essential or very important, not just because you would like to have them","cn":"需要；必需","ex":{"en":"Do you need any help?","cn":"你需要帮忙吗？"}},{"en":"used to show what you should or have to do","cn":"（表示应该或不得不做）有必要","ex":{"en":"All you need to do is complete this form.","cn":"你要做的就是填好这个表格。"}},{"en":"a situation when something is necessary or must be done","cn":"需要；必须","g":"[singular, uncountable]","ex":{"en":"to satisfy/meet/fulfil a need","cn":"满足某种需要"},"pos":"noun"},{"en":"a strong feeling that you want somebody/something or must have something","cn":"特别需要；迫切要求","g":"[countable, uncountable]","ex":{"en":"to fulfil an emotional need","cn":"满足感情的迫切需要"},"pos":"noun"},{"en":"the things that somebody requires in order to live in a comfortable way or achieve what they want","cn":"需要的事物；欲望","g":"[countable, usually plural]","ex":{"en":"First we will assess your financial needs.","cn":"我们首先会评估你经济上的需要。"},"pos":"noun"},{"en":"the state of not having enough food, money or support","cn":"（食物、钱或生活来源的）短缺，缺乏","g":"[uncountable]","ex":{"en":"The charity aims to provide assistance to people in need.","cn":"这家慈善机构的宗旨是帮助贫困者。"},"pos":"noun"},{"en":"used to state that something is/was not necessary or that only very little is/was necessary; used to ask if something is/was necessary","cn":"（表示没有必要或询问是否有必要）需要","ex":{"en":"You needn't bother asking Rick—I know he's too busy.","cn":"你不必费神去问里克，我知道他太忙了。"},"pos":"modal verb"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"(为做成某事或正常生活)要求有，必须有，需要","en":"If you need something, or need to do something, you cannot successfully achieve what you want or live properly without it.","ex":{"en":"He desperately needed money","cn":"他迫切需要钱。"}},{"pos":"VERB 动词","cn":"(表示某一做法对某事物或地方有益)应该，应当，需要","en":"If an object or place needs something doing to it, that action should be done to improve the object or place. If a task needs doing, it should be done to improve a particular situation.","ex":{"en":"The building needs quite a few repairs.","cn":"该建筑有好几处应该修缮。"}},{"pos":"N-SING 单数名词","cn":"必要;需要","en":"If there is a need for something, that thing would improve a situation or something cannot happen without it.","ex":{"en":"Mr Forrest believes there is a need for other similar schools throughout Britain","cn":"福里斯特先生认为全英国都需要有类似的学校。"}},{"pos":"MODAL 情态动词","cn":"不必，没有必要(用于告知或建议)","en":"If you say that someone needn't do something, you are telling them not to do it, or advising or suggesting that they should not do it.","ex":{"en":"'I'll put the key in the window.' — 'You needn't bother,' he said gruffly","cn":"“我会把钥匙放在窗户里。”——“不必麻烦了，”他粗声说道。"}},{"pos":"MODAL 情态动词","cn":"(与否定词连用)不必，没有必要","en":"If you tell someone that they needn't do something, or that something needn't happen, you are telling them that that thing is not necessary, in order to make them feel better.","ex":{"en":"You needn't worry","cn":"你不必担心。"}},{"pos":"MODAL 情态动词","cn":"(与否定词连用)准许不做，可以不做","en":"You use needn't when you are giving someone permission not to do something.","ex":{"en":"You needn't come again, if you don't want to","cn":"如果你不想来，可以不用再来。"}},{"pos":"MODAL 情态动词","cn":"(与否定词连用)未必，不一定","en":"If something need not be true, it is not necessarily true or not always true.","ex":{"en":"What is right for us need not be right for others","cn":"对我们来说是对的东西，对别人来说未必正确。"}},{"pos":"MODAL 情态动词","cn":"(与否定词连用)本来不必，本来不需要","en":"If someone needn't have done something, it was not necessary or useful for them to do it, although they did it.","ex":{"en":"She could have made the sandwich herself; her mum needn't have bothered to do anything","cn":"她本来可以自己做三明治的;她妈妈原本不必费心做任何事情。"}},{"pos":"MODAL 情态动词","cn":"(与否定词连用)无需说，不必说","en":"You use need in expressions such as I need hardly say and I needn't add to emphasize that the person you are talking to already knows what you are going to say.","ex":{"en":"I needn't add that if you fail to do as I ask, you will suffer the consequences.","cn":"如果你没按我的要求做的话，后果请自负——这话我就不必再说了吧。"}},{"pos":"MODAL 情态动词","cn":"还需要再说吗;还要我继续说吗","en":"You can use need in expressions such as 'Need I say more' and 'Need I go on' when you want to avoid stating an obvious consequence of something you have just said.","ex":{"en":"Mid-fifties, short black hair, grey moustache, distinctive Russian accent. Need I go on?","cn":"五十四五岁，黑色短发，灰色八字胡，明显的俄国口音，还需要我继续说吗？"}},{"pos":"PHRASE 短语","cn":"贫困的;困难中的","en":"People in need do not have enough of essential things such as money, food, or good health.","ex":{"en":"The education authorities have to provide for children in need","cn":"教育主管部门得救助贫困儿童。"}},{"pos":"PHRASE 短语","cn":"有…的需要;有…的必要","en":"If you are in need of something, you need it or ought to have it.","ex":{"en":"I was all right but in need of rest","cn":"我没事，就是需要休息一下。"}},{"pos":"PHRASE 短语","cn":"需要的话;如有必要(英国英语中亦作 if needs be)","en":"If you say that you will do something, especially an extreme action, if need be, you mean that you will do if it is necessary. In British English, you can also say if needs be .","ex":{"en":"They will now seek permission to take their case to the House of Lords, and, if need be, to the European Court of Human Rights.","cn":"他们现在将争取获准将案件呈交上议院审理，并且，如有必要，会上诉到欧洲人权法院。"}},{"pos":"PHRASE 短语","cn":"没有必要;不必","en":"You can tell someone that there's no need for them to do something as a way of telling them not to do it or of telling them to stop doing it, for example because it is unnecessary.","ex":{"en":"There's no need to call a doctor","cn":"没有必要叫医生。"}},{"pos":"PHRASE 短语","cn":"没人需要;没谁需要","en":"You can say 'Who needs something?' as a way of emphasizing that you think that this thing is unnecessary or not useful.","ex":{"en":"With apologies to my old history teacher, who needs history lessons?","cn":"这话对不住我亲爱的历史老师，不过有谁需要历史课呢？"}}]},"examples":[{"en":"I had no need to open the letter — I knew what it would say.","cn":"我没必要拆开那封信，我知道里面会说些什么。"},{"en":"What do you need your own computer for? You can use ours.","cn":"你干吗还要自己买电脑？你可以用我们的。"}]},"necktie":{"media":{"uk":"media/uk/necktie__gb_1.mp3","us":"media/us/necktie__us_1.mp3","img":["media/ldoce/img/neck_tie.jpg"]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"领带","en":"A necktie is a narrow piece of cloth that someone, usually a man, puts under his shirt collar and ties so that the ends hang down in front."}]},"oxford":{"phon":"ˈnektaɪ","pos":"noun","senses":[{"en":"a long narrow piece of cloth worn around the neck, especially by men, with a knot in front","cn":"领带"}]}},"nevertheless":{"media":{"uk":"media/uk/nevertheless__gb_1.mp3","us":"media/us/nevertheless__us_1.mp3"},"oxford":{"phon":"ˌnevəðəˈles","pos":"adverb","senses":[{"en":"despite something that you have just mentioned","cn":"尽管如此；不过；然而","ex":{"en":"There is little chance that we will succeed in changing the law. Nevertheless, it is important that we try.","cn":"我们几乎没有可能改变法律。不过，重要的是我们要努力争取。"}}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"然而;不过","en":"You use nevertheless when saying something that contrasts with what has just been said.","ex":{"en":"Most marriages fail after between five and nine years. Nevertheless, people continue to get married.","cn":"大部分婚姻在婚后第五至第九年间失败，然而，人们仍会选择结婚。"}}]},"examples":[{"en":"There is little chance that we will succeed in changing the law. Nevertheless, it is important that we try.","cn":"我们几乎没有可能改变法律。不过，重要的是我们要努力争取。"},{"en":"Our defeat was expected but it is disappointing nevertheless.","cn":"我们的失败是意料中的事，尽管如此，还是令人失望。"}]},"needing":{"oxford":{"phon":"niːd","pos":"verb","senses":[{"en":"to require sth/sb because they are essential or very important, not just because you would like to have them","cn":"需要；必需"},{"en":"used to show what you should or have to do （","cn":"表示应该或不得不做）有必要"}]},"media":{"uk":"media/uk/need__gb_1.mp3","us":"media/us/need__us_1.mp3"}},"needs":{"media":{"uk":"media/uk/needs__gb_1.mp3","us":"media/us/needs__us_1.mp3"},"oxford":{"phon":"niːdz","pos":"adverb","senses":[{"en":"in a way that cannot be avoided","cn":"必定；必须","ex":{"en":"We must needs depart.","cn":"我们必须离开。"}}]},"examples":[{"en":"We must needs depart.","cn":"我们必须离开。"}]},"new":{"media":{"uk":"media/uk/new__gb_1.mp3","us":"media/us/new__us_1.mp3"},"oxford":{"phon":"njuː","pos":"adjective","senses":[{"en":"not existing before; recently made, invented, introduced, etc.","cn":"刚出现的；新的；新近推出的","sc":"not existing before","ex":{"en":"Have you read her new novel?","cn":"你看过她新出的小说了吗？"}},{"en":"something that is new","cn":"新东西；新事物","g":"[uncountable]","sc":"not existing before","ex":{"en":"It was a good mix of the old and the new.","cn":"这是新旧的完美结合。"}},{"en":"recently bought","cn":"新买的","sc":"recently bought","ex":{"en":"Let me show you my new dress.","cn":"给你看看我新买的连衣裙。"}},{"en":"not used or owned by anyone before","cn":"没被用过的；未曾被人占有过的；崭新的","sc":"not used before","ex":{"en":"A second-hand car costs a fraction of a new one.","cn":"二手车的花费只是新车的零头。"}},{"en":"different from the previous one","cn":"有别于从前的；新颖的","sc":"different","ex":{"en":"I like your new hairstyle.","cn":"我喜欢你的新发型。"}},{"en":"already existing but not seen, experienced, etc. before; not familiar","cn":"刚体验到的；初见的；不熟悉的","sc":"not familiar","ex":{"en":"This is a new experience for me.","cn":"对于我来说，这是一次从未有过的经历。"}},{"en":"not yet familiar with something because you have only just started, arrived, etc.","cn":"初来乍到的；初学乍练的；新鲜的","sc":"recently arrived","ex":{"en":"You're new here, aren't you?","cn":"你是新来的，是吗？"}},{"en":"just beginning or beginning again","cn":"刚开始的；初始的；重新开始的","g":"[usually before noun]","sc":"just beginning","ex":{"en":"a new day","cn":"新的一天"}},{"en":"used in compounds to describe something that has recently happened","cn":"（用于构成复合词）新的，新近的","sc":"new-","ex":{"en":"He was enjoying his new-found freedom.","cn":"他享受着刚刚获得的自由。"}},{"en":"modern; of the latest type","cn":"现代的；最新型的","sc":"modern","ex":{"en":"the new morality","cn":"现代的道德"}},{"en":"having fresh energy, courage or health","cn":"富有朝气的；生气勃勃的","sc":"with fresh energy","ex":{"en":"Since he changed jobs he's looked like a new man.","cn":"他跳槽之后像换了一个人似的。"}},{"en":"only recently produced or developed","cn":"新近产生的；新开发的；时鲜的","sc":"recently produced","ex":{"en":"The new buds are appearing on the trees now.","cn":"树上现在露出了新芽。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"新的;刚出现的;新做的;新建的","en":"Something that is new has been recently created, built, or invented or is in the process of being created, built, or invented.","ex":{"en":"They've just opened a new hotel in the Stoke area","cn":"他们刚在斯托克地区开了一家新宾馆。"}},{"pos":"ADJ 形容词","cn":"崭新的;未使用过的","en":"Something that is new has not been used or owned by anyone.","ex":{"en":"That afternoon she went out and bought a new dress","cn":"那天下午她出门买了一件新裙子。"}},{"pos":"ADJ 形容词","cn":"更新的;替换的","en":"You use new to describe something which has replaced another thing, for example because you no longer have the old one, or it no longer exists, or it is no longer useful.","ex":{"en":"Under the new rules, some factories will cut emissions by as much as 90 percent","cn":"按照新规定，一些工厂的减排量要高达90%。"}},{"pos":"ADJ 形容词","cn":"新发现的;刚注意到的","en":"New is used to describe something that has only recently been discovered or noticed.","ex":{"en":"The new planet is about ten times the size of the earth.","cn":"新发现的行星大约是地球的10倍那么大。"}},{"pos":"ADJ 形容词","cn":"(一天或一年)新开始的，初始的","en":"A new day or year is the beginning of the next day or year.","ex":{"en":"The start of a new year is a good time to reflect on the many achievements of the past","cn":"新年伊始是反思过去一年诸多成就的好时机。"}},{"pos":"ADJ 形容词","cn":"(身份、地位等)新近获得的","en":"New is used to describe someone or something that has recently acquired a particular status or position.","ex":{"en":"...the usual exhaustion of a new mother","cn":"刚做妈妈的人通常会有的疲惫感"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"新接触的;不熟悉的","en":"If you are new to a situation or place, or if the situation or place is new to you, you have not previously seen it or had any experience of it.","ex":{"en":"She wasn't new to the company","cn":"公司对她早有耳闻。"}},{"pos":"ADJ 形容词","cn":"(土豆、胡萝卜、豆子等)时鲜的，早的","en":"New potatoes, carrots, or peas are produced early in the season for such vegetables and are usually small with a sweet flavour."},{"pos":"See also:","cn":"","en":"as good as new→see: ; to turn over a new leaf→see: ; a new lease of life→see: ; pastures new→see: ;"}]},"examples":[{"en":"‘Have you come across this before?’ ‘No, it's a new one on me.’ “","cn":"你以前碰到过这样的事吗？” “没有，从来没听说过。”"},{"en":"Despite his six years in politics, he was still regarded by many as the new kid on the block.","cn":"尽管他已经从政六年，但很多人仍把他视为初出茅庐。"}]},"nest":{"media":{"img":["media/ldoce/img/nest.jpg","media/pic/birds_comp.jpg"],"uk":"media/uk/nest__gb_1.mp3","us":"media/us/nest__us_1.mp3"},"oxford":{"phon":"nest","pos":"noun","senses":[{"en":"a hollow place or structure that a bird makes or chooses for laying its eggs in and sheltering its young","cn":"鸟巢；鸟窝","g":"[countable]","ex":{"en":"sparrows building a nest of twigs and dry grass","cn":"麻雀用树枝和干草筑巢"}},{"en":"a place where insects or other small creatures live and produce their young","cn":"巢穴；窝","g":"[countable]","ex":{"en":"a wasps’ nest","cn":"黄蜂窝"}},{"en":"a secret place which is full of bad people and their activities","cn":"藏匿处；秘密窝点","g":"[singular]","ex":{"en":"a nest of thieves","cn":"贼窝"}},{"en":"the home, thought of as the safe place where parents bring up their children","cn":"家；安乐窝","g":"[singular]","ex":{"en":"to leave the nest (= leave your parents’ home)","cn":"离开父母过独立生活"}},{"en":"a group or set of similar things that are made to fit inside each other","cn":"（套叠在一起的）一套物件","g":"[countable, usually singular]","ex":{"en":"a nest of tables","cn":"一套桌子"}},{"en":"to make and use a nest","cn":"筑巢；巢居","g":"[intransitive]","ex":{"en":"Thousands of seabirds are nesting on the cliffs.","cn":"成千上万的海鸟在悬崖上筑巢。"},"pos":"verb"},{"en":"to put types of information together, or inside each other, so that they form a single unit","cn":"嵌套（信息）","g":"[transitive]","lab":"specialist","pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(鸟)巢;(鸟)窝","en":"A bird's nest is the home that it makes to lay its eggs in.","ex":{"en":"I can see an eagle's nest on the rocks.","cn":"我能看到岩石上的鹰巢。"}},{"pos":"VERB 动词","cn":"(鸟类)筑巢，做窝","en":"When a bird nests somewhere, it builds a nest and settles there to lay its eggs.","ex":{"en":"Some species may nest in close proximity to each other.","cn":"一些鸟类会彼此紧挨着筑巢。"}},{"pos":"N-COUNT 可数名词","cn":"(昆虫或动物的)巢，穴","en":"A nest is a home that a group of insects or other creatures make in order to live in and give birth to their young in.","ex":{"en":"Some solitary bees make their nests in burrows in the soil.","cn":"一些独居蜂会把巢筑在田间的地洞里。"}},{"pos":"N-COUNT 可数名词","cn":"安乐窝;安适的地方","en":"You can refer to a place as your nest when it is your home or where you feel comfortable and relaxed.","ex":{"en":"My wife seems to be building a nest of her own at Osborne House","cn":"我夫人像是要把奥斯本庄园变成自己的安乐窝。"}},{"pos":"N-COUNT 可数名词","cn":"老巢;窟;秘密窝点;(贼窟中的)一帮","en":"You can use nest to refer to a place where something bad is being done or to the people there who are doing it.","ex":{"en":"...Biarritz, notorious in those days as a nest of spies","cn":"比亚里茨，那时候出了名的间谍老巢"}},{"pos":"PHRASE 短语","cn":"营私;自肥","en":"If you say that someone is feathering their nest, you mean that they are getting a lot of money out of something, so that they can lead a comfortable life.","ex":{"en":"Mary's much more interested in doing things for other people than feathering her own nest.","cn":"相比追逐私利，玛丽更乐意帮助他人。"}},{"pos":"PHRASE 短语","cn":"自立门户;独立生活","en":"When children fly the nest, they leave their parents' home to live on their own.","ex":{"en":"When their children had flown the nest, he and his wife moved to a thatched cottage in Dorset.","cn":"孩子们独立生活后，他和妻子搬到多塞特的茅草屋去住了。"}},{"pos":"","cn":"","en":"a hornet's nest→see: ;"}]},"examples":[{"en":"Thousands of seabirds are nesting on the cliffs.","cn":"成千上万的海鸟在悬崖上筑巢。"},{"en":"to leave the nest (= leave your parents' home)","cn":"离开父母过独立生活"}]},"net":{"media":{"uk":"media/uk/net__gb_1.mp3","us":"media/us/net__us_1.mp3","img":["media/ldoce/img/fishing_equipment.jpg"]},"oxford":{"phon":"net","pos":"noun","senses":[{"en":"material that is made of string, thread or wire twisted or tied together, with small spaces in between; a piece of this material used for a particular purpose","cn":"网；网状物","g":"[countable, uncountable]","ex":{"en":"Unfortunately the animals are often caught in fishing nets.","cn":"不幸的是，这些动物经常被渔网套住。"}},{"en":"the frame covered in net that forms the goal","cn":"球门网","g":"[singular]","ex":{"en":"to kick the ball into the back of the net","cn":"把球踢进网窝"}},{"en":"the piece of net between the two players that the ball goes over","cn":"球网","g":"[singular]","ex":{"en":"She hit her second serve straight into the net.","cn":"她的第二个发球直接入网。"}},{"en":"a piece of ground with a net around it, used for practising batting and bowling","cn":"（有网包围的）练习场","g":"[countable, usually plural]","ex":{"en":"He practised bowling all morning in the nets.","cn":"他整个早上都在网内练习保龄球。"}},{"en":"the internet","cn":"互联网","g":"[singular]","lab":"informal","ex":{"en":"He spends his time playing computer games and surfing the net.","cn":"他把时间花在玩电脑游戏和上网上。"}},{"en":"a network of radios or computers that are connected to each other","cn":"（无线通信或计算机的）网络","g":"[countable]","ex":{"en":"A call on the radio net went out that there had been a crash.","cn":"无线电网络上传来了发生车祸的消息。"}},{"en":"an amount of money net is the amount that remains when nothing more is to be taken away","cn":"净得的；纯的","ex":{"en":"a salary of $50 000 net","cn":"5 万美元的实得工资"},"pos":"adverb"},{"en":"a net amount of money is the amount that remains when nothing more is to be taken away","cn":"净得的；纯的","g":"[usually before noun]","ex":{"en":"a net profit of £500","cn":"500 英镑的纯利润"},"pos":"adjective"},{"en":"the net weight of something is the weight without its container or the material it is wrapped in","cn":"净的","g":"[only before noun]","ex":{"en":"450 gms net weight","cn":"净重 450 克"},"pos":"adjective"},{"en":"final, after all the important facts have been included","cn":"最后的；最终的","g":"[only before noun]","ex":{"en":"The net result is that small shopkeepers are being forced out of business.","cn":"最终结果是小店主被迫停业。"},"pos":"adjective"},{"en":"to earn an amount of money as a profit after you have paid tax on it","cn":"净赚；净得","ex":{"en":"The sale of paintings netted £17 000.","cn":"卖画净得 17 000 英镑。"},"pos":"verb"},{"en":"to catch something, especially fish, in a net","cn":"（尤指）用网捕捉（鱼等）","pos":"verb"},{"en":"to catch somebody or obtain something with skill","cn":"（巧妙地）捕获，得到","ex":{"en":"A swoop by customs officers netted a large quantity of drugs.","cn":"海关人员突击搜查，缉获大量毒品。"},"pos":"verb"},{"en":"to kick or hit a ball into the goal","cn":"（将球）踢入球门，射入球门","lab":"especially British English","ex":{"en":"He has netted 21 goals so far this season.","cn":"这个赛季至今他已射入 21 球。"},"pos":"verb"},{"en":"to cover something with a net or nets","cn":"用网覆盖","ex":{"en":"It is a good idea to net the strawberry plants.","cn":"将草莓植株网起来是个好主意。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"网;网状物","en":"Net is a kind of cloth that you can see through. It is made of very fine threads woven together so that there are small equal spaces between them."},{"pos":"N-COUNT 可数名词","cn":"(保护性)网罩","en":"A net is a piece of netting which is used as a protective covering for something, for example to protect vegetables from birds.","ex":{"en":"I threw aside my mosquito net and jumped out of bed.","cn":"我把蚊帐甩到一边，跳下床来。"}},{"pos":"N-COUNT 可数名词","cn":"(用以捕鱼、昆虫或动物的)渔网，罗网","en":"A net is a piece of netting which is used for catching fish, insects, or animals.","ex":{"en":"Several fishermen sat on wooden barrels, tending their nets.","cn":"几个渔夫坐在木桶上修补渔网。"}},{"pos":"N-SING 单数名词","cn":"同 Internet","en":"The Net is the same as the Internet ."},{"pos":"VERB 动词","cn":"(用网)捕捉，罩，围","en":"If you net a fish or other animal, you catch it in a net.","ex":{"en":"I'm quite happy to net a fish and then let it go","cn":"我特别喜欢用网捕到鱼后再把它放了。"}},{"pos":"N-COUNT 可数名词","cn":"(网球场等的)球网","en":"In games such as tennis, the net is the piece of netting across the centre of the court which the ball has to go over."},{"pos":"N-COUNT 可数名词","cn":"(足球或曲棍球场的)有网球门","en":"The net on a football or hockey field is the framework with netting over it which is attached to the back of the goal.","ex":{"en":"He let the ball slip through his grasp and into the net.","cn":"球从他的掌中滑出，钻进了球门。"}},{"pos":"N-COUNT 可数名词","cn":"(篮球)球网","en":"In basketball, the net is the netting which hangs from the metal hoop. You score goals by throwing the ball through the hoop and netting."},{"pos":"VERB 动词","cn":"(篮球或足球)得分，进(球)","en":"In basketball or football, when you net a goal, you score a goal.","ex":{"en":"Centre half Tiler netted his first goal for the club.","cn":"中前卫泰勒为俱乐部射进了他的第一粒进球。"}},{"pos":"VERB 动词","cn":"(尤指运用技巧)获取，得到","en":"If you net something, you manage to get it, especially by using skill.","ex":{"en":"They took to the water intent on netting the £250,000 reward offered for conclusive proof of the monster's existence.","cn":"他们前往那片水域，打算找到怪物存在的确凿证据，以获得为此设立的25万英镑奖金。"}},{"pos":"VERB 动词","cn":"捕获;抓获;缴获","en":"When a police operation nets a number of people or things, they catch those people or find those things.","ex":{"en":"Secret investigations have netted ninety staff suspected of fraud and theft","cn":"秘密调查已抓获90名涉嫌欺诈盗窃的职员。"}},{"pos":"VERB 动词","cn":"净得;净赚","en":"If you net a particular amount of money, you gain it as profit after all expenses have been paid.","ex":{"en":"Last year he netted a cool 3 million pounds by selling his holdings","cn":"去年他通过出售自己持有的股份获得了整整300万英镑的净收入。"}},{"pos":"PHRASE 短语","cn":"从更大范围考虑;做更大范围的尝试","en":"If you cast your net wider, you look for or consider a greater variety of things.","ex":{"en":"The security forces are casting their net wider.","cn":"安全部队正在更广泛地布网。"}},{"pos":"PHRASE 短语","cn":"(罪犯)漏网，逃脱","en":"If criminals slip through the net, they avoid being caught by the system or trap that was meant to catch them.","ex":{"en":"Officials fear some of the thugs identified by British police may have slipped through the net.","cn":"官员们担心英国警方指认的一些罪犯可能已成为漏网之鱼。"}},{"pos":"PHRASE 短语","cn":"(在体制中)被遗漏，被遗忘","en":"You use slip through the net or fall through the net to describe a situation where people are not properly cared for by the system that is intended to help them.","ex":{"en":"And a number of African countries, too, are slipping through the net","cn":"并且一些非洲国家也被漏掉了。"}},{"pos":"ADJ 形容词","cn":"净数的;纯的","en":"A net amount is one which remains when everything that should be subtracted from it has been subtracted.","ex":{"en":"...a rise in sales and net profit","cn":"销售和纯利润的增长"}},{"pos":"ADJ 形容词","cn":"(重量)净的，纯的","en":"The net weight of something is its weight without its container or the material that has been used to wrap it.","ex":{"en":"...350 mg net weight.","cn":"净重350毫克"}},{"pos":"ADJ 形容词","cn":"(结果)最终的，最后的","en":"A net result is a final result after all the details have been considered or included.","ex":{"en":"We have a net gain of nearly 50 seats, the biggest for any party in Scotland","cn":"我们最终获得了近50个席位，是苏格兰政党里赢得席位最多的。"}}]},"examples":[{"en":"The net result is that small shopkeepers are being forced out of business.","cn":"最终结果是小店主被挤出了这个行业。"},{"en":"Canada is now a substantial net importer of medicines (= it imports more than it exports).","cn":"加拿大现在是一个药物净进口大国。"}]},"necessary":{"media":{"uk":"media/uk/necessary__gb_1.mp3","us":"media/us/necessary__us_1.mp3"},"oxford":{"phon":"ˈnesəsəri","pos":"adjective","senses":[{"en":"that is needed for a purpose or a reason","cn":"必需的；必要的","ex":{"en":"It may be necessary to buy a new one.","cn":"也许有必要买个新的了。"}},{"en":"that must exist or happen and cannot be avoided","cn":"必然的；无法避免的","g":"[only before noun]","ex":{"en":"This is a necessary consequence of progress.","cn":"这是事情发展的必然后果。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"必要的;必需的","en":"Something that is necessary is needed in order for something else to happen.","ex":{"en":"I kept the engine running because it might be necessary to leave fast","cn":"我没让发动机熄火，因为也许需要迅速离开。"}},{"pos":"ADJ 形容词","cn":"(结果或联系)必然的，势必的","en":"A necessary consequence or connection must happen or exist, because of the nature of the things or events involved.","ex":{"en":"Wastage was no doubt a necessary consequence of war","cn":"巨大的损耗无疑是战争的必然结果。"}},{"pos":"N-PLURAL 复数名词","cn":"基本生活必需;必需品","en":"Necessaries are things, such as food or clothing, that you need to have in order to live.","ex":{"en":"...a small parcel of necessaries tied up in a handkerchief and carried on a stick.","cn":"用手绢包好挑在棍子上的一小包生活必需品"}},{"pos":"PHRASE 短语","cn":"如果必要的话","en":"If you say that something will happen if necessary ,when necessary, or where necessary, you mean that it will happen if it is necessary, when it is necessary, or where it is necessary.","ex":{"en":"If necessary, the airship can stay up there for days to keep out of danger","cn":"必要时，飞艇能在那里停留数天以躲避危险。"}}]},"examples":[{"en":"If necessary, you can contact me at home.","cn":"必要的话，你可以打电话到我家找我。"},{"en":"Only use your car when absolutely necessary.","cn":"非用不可的时候才用你的汽车。"}]},"negativity":{"oxford":{"phon":"ˌneɡəˈtɪvəti","pos":"noun","senses":[{"en":"the fact of tending to consider only the bad side of something/somebody; a lack of enthusiasm or hope","cn":"消极；悲观；缺乏热情"}]},"media":{"uk":"media/uk/negativity__gb_1.mp3","us":"media/us/negativity__us_1.mp3"}},"neat":{"oxford":{"phon":"niːt","pos":"adjective","senses":[{"en":"tidy and in order; carefully done or arranged","cn":"整洁的；整齐的；有序的","ex":{"en":"She kept her desk extremely neat.","cn":"她的桌子保持得非常干净整洁。"}},{"en":"liking to keep things tidy and in order; looking tidy or doing things in a tidy way","cn":"有条理的；爱整洁的","lab":"informal","ex":{"en":"Try and be neater!","cn":"干净整洁点！"}},{"en":"small, with an attractive shape or appearance","cn":"小巧优雅的","ex":{"en":"her neat figure","cn":"她那娇小玲珑的身材"}},{"en":"simple but clever","cn":"简洁的；睿智的；灵巧的","ex":{"en":"a neat explanation","cn":"简明的解释"}},{"en":"good; excellent","cn":"好的；极好的","lab":"North American English, informal，，","ex":{"en":"It's a really neat movie.","cn":"这真是一部极好的电影。"}},{"en":"not mixed with water or anything else","cn":"未掺水的；纯的","lab":"British English","ex":{"en":"neat whisky","cn":"纯威士忌酒"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"整洁的;整齐的","en":"A neat place, thing, or person is tidy and smart, and has everything in the correct place.","ex":{"en":"So they left her in the neat little house, alone with her memories","cn":"于是他们把她一个人留在整洁的小房子里，只有记忆陪着她。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"爱整洁的;会收拾的","en":"Someone who is neat keeps their home or possessions tidy, with everything in the correct place.","ex":{"en":"'That's not like Alf,' he said, 'leaving papers muddled like that. He's always so neat.'","cn":"他说道：“这不像是阿尔夫的风格，他不会把文件弄得那么乱。他一向很爱整洁。”"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"匀整的;秀气的;小巧优雅的","en":"A neat object, part of the body, or shape is quite small and has a smooth outline.","ex":{"en":"...a faded woman with neat features.","cn":"姿色虽衰但五官清秀的女人"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(行动等)干净利落的，利索的","en":"A neat movement or action is done accurately and skilfully, with no unnecessary movements.","ex":{"en":"A neat move between Black and Keane left Nigel Clough in the clear, but his shot skimmed wide of the far post.","cn":"奈杰尔·克拉夫凭借一次漂亮的跑位在布莱克和基恩之间扯出了空当儿，但是他的射门却大大偏出了远门柱。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"巧妙的;简洁的;简便易行的","en":"A neat way of organizing, achieving, explaining, or expressing something is clever and convenient.","ex":{"en":"It had been such a neat, clever plan","cn":"这曾是个如此巧妙、机智的计划。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"很好的;很棒的","en":"If you say that something is neat, you mean that it is very good.","ex":{"en":"'Oh, those new apartments are really neat,' the girl babbled on","cn":"那个女孩赞不绝口地说：“噢，那些新公寓真是非常棒。”"}},{"pos":"ADJ 形容词","cn":"(烈性酒)未掺水的，纯的","en":"When someone drinks strong alcohol neat, they do not add a weaker liquid such as water to it.","ex":{"en":"He poured himself a brandy and swallowed it neat","cn":"他给自己倒了一杯白兰地，没兑水就一饮而尽。"}}]},"media":{"uk":"media/uk/neat__gb_1.mp3","us":"media/us/neat__us_1.mp3"},"examples":[{"en":"They sat in her neat and tidy kitchen.","cn":"他们坐在她那干净整齐的厨房里。"},{"en":"She summarized her plan very neatly.","cn":"她非常简明地总结了她的计划。"}]},"negro":{"media":{"uk":"media/uk/negro__gb_1.mp3","us":"media/us/negro__us_1.mp3"},"oxford":{"phon":"ˈniːɡrəʊ","pos":"noun","senses":[{"en":"an old-fashioned, now offensive word for a person with dark skin, especially one who originally came from or whose ancestors came from Africa","cn":"黑人"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"黑人","en":"A Negro is someone with dark skin who comes from Africa or whose ancestors came from Africa."}]}},"neighborhoods":{"oxford":{"phon":"ˈneɪbəhʊd","pos":"noun","senses":[{"en":"a district or an area of a town; the people who live there","cn":"街区；城区；（统称）某街区（或城区）的居民"},{"en":"the area that you are in or the area near a particular place","cn":"所在地；邻近的地方"}]}},"nelson":{"media":{"uk":"media/uk/nelson__gb_1.mp3","us":"media/us/nelson__us_1.mp3"},"oxford":{"phon":"ˈnelsn","pos":"noun","senses":[{"en":"a move in which a wrestler stands behind his/her opponent, puts one or both arms under the opponent’s arm(s) and holds the back of the opponent’s neck. When done with one arm it is called a half nelson, and with both arms a full nelson.","cn":"肩下握颈（从背后通过对手腋下钩住其后颈的摔跤动作，分单臂握颈和双臂握颈）"}]}},"nearly":{"media":{"uk":"media/uk/nearly__gb_1.mp3","us":"media/us/nearly__us_1.mp3"},"oxford":{"phon":"ˈnɪəli","pos":"adverb","senses":[{"en":"almost; not quite; not completely","cn":"几乎；差不多；将近","lab":"British English","ex":{"en":"The bottle's nearly empty.","cn":"这瓶子差不多空了。"}}]},"collins":{"senses":[{"pos":"ADV-GRADED 副词","cn":"几乎;差不多","en":"Nearly is used to indicate that something is not quite the case, or not completely the case.","ex":{"en":"Goldsworth stared at me in silence for nearly twenty seconds","cn":"将近20秒的时间，戈兹沃思就那么一声不响地盯着我看。"}},{"pos":"ADV-GRADED 副词","cn":"即将;就要","en":"Nearly is used to indicate that something will soon be the case.","ex":{"en":"It was already nearly eight o'clock","cn":"已经快8点了。"}},{"pos":"PHRASE 短语","cn":"远远不;根本不;远非","en":"You use not nearly to emphasize that something is not the case.","ex":{"en":"Father's flat in Paris wasn't nearly as grand as this","cn":"爸爸在法国的公寓远不如这处宽敞。"}}]},"examples":[{"en":"There isn't nearly enough time to get there now.","cn":"现在根本没有足够的时间赶到那儿。"},{"en":"I've worked here for nearly two years.","cn":"我已经在这里工作了将近两年。"}]},"nearsighted":{"media":{"uk":"media/uk/nearsighted__gb_1.mp3","us":"media/us/nearsighted__us_1.mp3"},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"近视的","en":"Someone who is near-sighted cannot see distant things clearly.","ex":{"en":"The girl squinted at the photograph. She seemed to be nearsighted.","cn":"女孩眯起眼睛看照片。她好像近视。"}}]},"oxford":{"phon":"ˌnɪəˈsaɪtɪd","pos":"adjective","senses":[{"en":"able to see things clearly only if they are very close to you","cn":"近视的"}]}},"next":{"media":{"uk":"media/uk/next__gb_1.mp3","us":"media/us/next__us_1.mp3"},"oxford":{"phon":"nekst","pos":"adjective","senses":[{"en":"coming straight after somebody/something in time, order or space","cn":"下一个的；紧接着的；接下来的","lab":"informal","ex":{"en":"The next train to Baltimore is at ten.","cn":"下一趟去巴尔的摩的列车十点钟开。"}},{"en":"the Monday, week, etc. immediately following","cn":"紧随其后的；下一个的","ex":{"en":"Next Thursday is 12 April.","cn":"下个星期四是 4 月 12 日。"}},{"en":"after something else; then; afterwards","cn":"紧接着；随后","ex":{"en":"What happened next?","cn":"随后发生了什么？"},"pos":"adverb"},{"en":"following in the order mentioned","cn":"其次的；依次的；仅次于…的","ex":{"en":"Jo was the next oldest after Martin.","cn":"马丁下面年龄最大的就是乔了。"},"pos":"adverb"},{"en":"used in questions to express surprise","cn":"（用于询问，表示吃惊）","ex":{"en":"You're going bungee jumping? Whatever next?","cn":"你要去蹦极？还想干什么？"},"pos":"adverb"},{"en":"a person or thing that is next","cn":"下一位；下一个；下一件","ex":{"en":"One moment he wasn't there, the next he was.","cn":"他前一刻还不在那里，一会儿又在了。"},"pos":"noun"},{"en":"any of a group of high-street shops in Britain selling fashionable clothes and things for the home","cn":"在英国的一些高街商店中，任何一家出售流行服装和家居用品的商店","pos":""}]},"collins":{"senses":[{"pos":"ORD 序数词","cn":"紧接在后的;接下去的","en":"The next period of time, event, person, or thing is the one that comes immediately after the present one or after the previous one.","ex":{"en":"I got up early the next morning.","cn":"第二天早晨我早早地起床了。"}},{"pos":"DET 限定词","cn":"紧接在后的;下一个的","en":"You use next in expressions such as next Friday ,next day and next year to refer, for example, to the first Friday, day, or year that comes after the present or previous one.","ex":{"en":"Let's plan a big night next week","cn":"我们下周组织一次盛大的晚会吧。"}},{"pos":"ADJ 形容词","cn":"紧邻的;贴近的","en":"The next place or person is the one that is nearest to you or that is the first one that you come to.","ex":{"en":"Grace sighed so heavily that Trish could hear it in the next room","cn":"格雷斯重重的叹息声连隔壁房间的特里斯都能听见。"}},{"pos":"ADV 副词","cn":"接着;随后","en":"The thing that happens next is the thing that happens immediately after something else.","ex":{"en":"Next, close your eyes then screw them up tight","cn":"接着，合上双眼，然后再用力闭紧。"}},{"pos":"ADV 副词","cn":"又一次;再次","en":"When you next do something, you do it for the first time since you last did it.","ex":{"en":"I next saw him at his house in Berkshire","cn":"我在伯克郡他的家中再次见到了他。"}},{"pos":"ADV 副词","cn":"仅次于…的;第二…的","en":"You use next to say that something has more of a particular quality than all other things except one. For example, the thing that is next best is the one that is the best except for one other thing.","ex":{"en":"The one thing he didn't have was a son. I think he's felt that a grandson is the next best thing","cn":"他唯一缺的就是个儿子，我想他觉得有个外孙也不错。"}},{"pos":"PHRASE 短语","cn":"再下(周);下下(周)","en":"You use after next in expressions such as the week after next to refer to a period of time after the next one. For example, when it is May, the month after next is July.","ex":{"en":"...the party's annual conference, to be held in Bournemouth the week after next.","cn":"下下周在伯恩茅斯举行的该党年会"}},{"pos":"PHRASE 短语","cn":"跟别人一样","en":"If you say that you do something or experience something as much as the next person, you mean that you are no different from anyone else in the respect mentioned.","ex":{"en":"I enjoy pleasure as much as the next person","cn":"我和别人一样愉快。"}},{"pos":"PHRASE 短语","cn":"接下来(我)所知道的;出乎意料的是","en":"You can say the next thing I knew to suggest that a new situation which you are describing was surprising because it happened very suddenly.","ex":{"en":"I had leaned over to pick up some change, and the next thing I knew I felt this terrible pain in my ankle.","cn":"我俯身去拿那些零钱，接下来就突然感到脚踝剧痛。"}},{"pos":"PREP-PHRASE 短语介词","cn":"紧靠…旁边;在…近旁;贴近","en":"If one thing is next to another thing, it is at the other side of it.","ex":{"en":"She sat down next to him on the sofa.","cn":"她紧挨着他在沙发上坐下了。"}},{"pos":"PREP-PHRASE 短语介词","cn":"居于…之后;次于","en":"You use next to in order to give the most important aspect of something when comparing it with another aspect.","ex":{"en":"Her children were the number two priority in her life next to her career","cn":"对她而言，孩子们的重要性仅次于她的事业。"}},{"pos":"PHRASE 短语","cn":"(用于否定词前)几乎，差不多","en":"You use next to before a negative, or a word that suggests something negative, to mean almost, but not completely.","ex":{"en":"Johnson still knew next to nothing about tobacco","cn":"约翰逊仍然对烟草几乎一无所知。"}}]},"examples":[{"en":"( informal ) Round here, you leave school at sixteen and next thing you know , you're married with three kids.","cn":"这一带的人十六岁中学毕业，接着就结婚，生三个孩子。"},{"en":"Janet’s sitting nearest to the window (= of all the people in the room).","cn":"珍妮特坐在（屋里所有人中）离窗户最近的地方。"}]},"negotiation":{"oxford":{"phon":"nɪˌɡəʊʃiˈeɪʃn","pos":"noun","senses":[{"en":"formal discussion between people who are trying to reach an agreement","cn":"谈判；磋商；协商","lab":"US English","ex":{"en":"peace/trade/contract negotiations","cn":"和平／贸易／合同谈判"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"(尤指商业或政治方面的)谈判，协商，磋商","en":"Negotiations are formal discussions between people who have different aims or intentions, especially in business or politics, during which they try to reach an agreement.","ex":{"en":"We have had meaningful negotiations and I believe we are very close to a deal","cn":"我们已进行了有益的磋商，我相信我们很快能成交。"}}]},"media":{"uk":"media/uk/negotiation__gb_1.mp3","us":"media/us/negotiation__us_1.mp3"},"examples":[{"en":"The rent is a matter for negotiation between the landlord and the tenant.","cn":"租金可以由房东和租户协商确定。"},{"en":"A contract is prepared in negotiation with our clients.","cn":"我们和客户协商起草了一份合同。"}]},"ness":{"oxford":{"phon":"nəs","pos":"suffix","senses":[{"en":"the quality, state or character of","cn":"…的性质（或状态、特点）","ex":{"en":"dryness","cn":"干燥"}}]}},"neighbourhood":{"media":{"uk":"media/uk/neighbourhood__gb_1.mp3","us":"media/us/neighbourhood__us_1.mp3"},"oxford":{"phon":"ˈneɪbəhʊd","pos":"noun","senses":[{"en":"a district or an area of a town; the people who live there","cn":"街区；城区；（统称）某街区（或城区）的居民","ex":{"en":"We grew up in the same neighbourhood.","cn":"我们在同一个街区长大。"}},{"en":"the area that you are in or the area near a particular place","cn":"所在地；邻近的地方","ex":{"en":"We searched the surrounding neighbourhood for the missing boy.","cn":"我们在附近寻找失踪的男孩儿。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(城镇中的)居住区，地段，街坊","en":"A neighbourhood is one of the parts of a town where people live.","ex":{"en":"It seemed like a good neighbourhood to raise my children.","cn":"它看起来像是一个有利于我的孩子们成长的理想居住区。"}},{"pos":"N-COUNT 可数名词","cn":"周边地区;邻居;社区","en":"The neighbourhood of a place or person is the area or the people around them.","ex":{"en":"He was born and grew up in the Flatbush neighbourhood of Brooklyn","cn":"他出生在布鲁克林的弗拉特布什一带，并在那儿长大成人。"}},{"pos":"PREP-PHRASE 短语介词","cn":"大约;在…左右","en":"In the neighbourhood of a number means approximately that number.","ex":{"en":"He's won in the neighbourhood of four million dollars","cn":"他已经赢了约400万美元。"}},{"pos":"PHRASE 短语","cn":"在…附近;靠近","en":"A place in the neighbourhood of another place is near it.","ex":{"en":"...the loss of woodlands in the neighbourhood of large towns.","cn":"大城镇附近林地的丧失"}}]},"examples":[{"en":"He shouted so loudly that the whole neighbourhood could hear him.","cn":"他叫得那么大声，整条街的人都能听到。"},{"en":"Manhattan is divided into distinct neighborhoods.","cn":"曼哈顿分为几个区，风格各异。"}]},"neither":{"media":{"uk":"media/uk/neither__gb_1.mp3","us":"media/us/neither__us_1.mp3"},"oxford":{"phon":"ˈnaɪðə(r)","pos":"determiner, pronoun","senses":[{"en":"not one nor the other of two things or people","cn":"两者都不","ex":{"en":"Neither answer is correct.","cn":"两个答案都不对。"}},{"en":"used to show that a negative statement is also true of somebody/something else","cn":"（否定的陈述同样适用于其他人或物）也不","lab":"informal","ex":{"en":"He didn't remember and neither did I.","cn":"他没记住，我也忘了。"},"pos":"adverb"},{"en":"used to show that a negative statement is true of two things","cn":"（否定的陈述适用于两方面）既不…也不…","ex":{"en":"I neither knew nor cared what had happened to him.","cn":"我既不知道也不关心他出了什么事。"},"pos":"adverb"}]},"collins":{"senses":[{"pos":"CONJ-COORD-NEG 连词","cn":"既不…(也不…)","en":"You use neither in front of the first of two or more words or expressions when you are linking two or more things which are not true or do not happen. The other thing is introduced by 'nor'.","ex":{"en":"Professor Hisamatsu spoke neither English nor German","cn":"久松教授既不会讲英语，也不会讲德语。"}},{"pos":"DET-NEG 否定限定词","cn":"两个都不;(两者之中)无一个","en":"You use neither to refer to each of two things or people, when you are making a negative statement that includes both of them.","ex":{"en":"At first, neither man could speak.","cn":"起初，两个人都不会说。"}},{"pos":"CONJ-COORD-NEG 连词","cn":"也不;都不","en":"If you say that one person or thing does not do something and neither does another, what you say is true of all the people or things that you are mentioning.","ex":{"en":"I never learned to swim and neither did they","cn":"我从没学过游泳，他们也没有。"}},{"pos":"CONJ-COORD-NEG 连词","cn":"(用于否定陈述后，强调要引出另一否定陈述)也不","en":"You use neither after a negative statement to emphasize that you are introducing another negative statement.","ex":{"en":"I can't ever recall Dad hugging me. Neither did I sit on his knee.","cn":"我不记得爸爸曾经抱过我，我也没在他膝盖上坐过。"}},{"pos":"PHRASE 短语","cn":"不相干;无关紧要","en":"If you say that something is neither here nor there, you mean that it does not matter because it is not a relevant point.","ex":{"en":"'I'd never heard of her before I came here.' — 'That is neither here nor there.'","cn":"“来之前我从未听说过她。”——“那没什么。”"}}]},"examples":[{"en":"‘Which do you like?’ ‘Neither. I think they're both ugly.’ “","cn":"你喜欢哪一个？” “两个都不喜欢。我觉得两个都很难看。”"},{"en":"They produced two reports, neither of which contained any useful suggestions.","cn":"他们提交了两个报告，都没有任何有用的建议。"}]},"neutral":{"media":{"uk":"media/uk/neutral__gb_1.mp3","us":"media/us/neutral__us_1.mp3"},"oxford":{"phon":"ˈnjuːtrəl","pos":"adjective","senses":[{"en":"not supporting or helping either side in a disagreement, competition, etc.","cn":"中立的；持平的；无倾向性的","sc":"in disagreement/contest","ex":{"en":"Journalists are supposed to be politically neutral.","cn":"新闻工作者在政治上应持中立态度。"}},{"en":"not belonging to any of the countries that are involved in a war; not supporting any of the countries involved in a war","cn":"中立国的；中立的","sc":"in war","ex":{"en":"neutral territory/waters","cn":"中立国的领土／领海"}},{"en":"deliberately not expressing any strong feeling","cn":"中性的；不含褒贬义的","sc":"without strong feeling/influence","ex":{"en":"‘So you told her?’ he said in a neutral tone of voice.","cn":"“那么你告诉她了？”他平静地说。"}},{"en":"not affected by something","cn":"不受影响的；没有倾向的","sc":"without strong feeling/influence","ex":{"en":"He believes that technology is morally neutral until it is applied.","cn":"他认为技术在投入应用以前是无关乎道德的。"}},{"en":"not very bright or strong, such as grey or light brown","cn":"素净的；淡素的；不鲜艳的","sc":"colour","ex":{"en":"a neutral colour scheme","cn":"中性色的色彩搭配"}},{"en":"neither acid nor alkaline","cn":"中性的；非酸性又非碱性的","sc":"chemistry"},{"en":"having neither a positive nor a negative electrical charge","cn":"中性的；不带电的","sc":"electrical","ex":{"en":"the neutral wire in a plug","cn":"插头里的零线"}},{"en":"the position of the gears of a vehicle in which no power is carried from the engine to the wheels","cn":"（汽车排挡）空挡","g":"[uncountable]","sc":"in vehicle","ex":{"en":"to leave the car in neutral","cn":"将车的排挡置于空挡位"},"pos":"noun"},{"en":"a person or country that does not support either side in a disagreement, competition or war","cn":"中立者；中立国","g":"[countable]","sc":"in disagreement/war","pos":"noun"},{"en":"a colour that is not bright or strong, such as grey or light brown","cn":"中性色；无彩色；素净色","g":"[countable]","sc":"colour","ex":{"en":"The room was decorated in neutrals.","cn":"房间用了中性色来装饰。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(个人或国家)持中立态度的，中立的，无倾向性的","en":"If a person or country adopts a neutral position or remains neutral, they do not support anyone in a disagreement, war, or contest.","ex":{"en":"Let's meet on neutral territory","cn":"我们在中立地区会面吧。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(声音或表情)不露声色的，平淡的","en":"If someone speaks in a neutral voice or if the expression on their face is neutral, they do not show what they are thinking or feeling.","ex":{"en":"Isabel put her magazine down and said in a neutral voice, 'You're very late, darling.'","cn":"伊莎贝尔放下杂志，平静地说道：“亲爱的，你来得太晚了。”"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"中性的;不引起变化的","en":"If you say that something is neutral, you mean that it does not have any effect on other things because it lacks any significant qualities of its own, or it is an equal balance of two or more different qualities, amounts, or ideas.","ex":{"en":"Three in every five interviewed felt that the Budget was neutral and they would be no better off","cn":"五分之三的受访者觉得该预算案不好不坏，他们的境况不会好到哪里去。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(话语)模糊的，中立的，不含褒贬义的","en":"If someone uses neutral language, they choose words which do not indicate that they approve or disapprove of something.","ex":{"en":"Both sides had agreed to use neutral terms in their references to each other, avoiding controversial ones","cn":"双方已达成协议，在提及对方时使用中性的词语，避免有争议的字眼。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(车辆排挡的)空挡","en":"Neutral is the position between the gears of a vehicle such as a car, in which the gears are not connected to the engine.","ex":{"en":"Graham put the van in neutral and jumped out into the road.","cn":"格雷厄姆把货车挂到空挡，自己跳到马路上。"}},{"pos":"ADJ 形容词","cn":"(电线)中性的","en":"In an electrical device or system, the neutral wire is one of the three wires needed to complete the circuit so that the current can flow. The other two wires are called the earth wire and the live or positive wire."},{"pos":"COLOUR 颜色词","cn":"灰暗的;素净的;无色的","en":"Neutral is used to describe things that have a pale colour such as cream or grey, or that have no colour at all.","ex":{"en":"At the horizon the land mass becomes a continuous pale neutral grey","cn":"陆地在地平线处变成了一片浅灰。"}},{"pos":"ADJ 形容词","cn":"不带电的","en":"In physics, neutral is used to describe things such as atomic particles that have neither a positive nor a negative charge.","ex":{"en":"A neutron is simply a neutral particle in the nucleus of an atom.","cn":"中子就是原子核里不带电的粒子。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(化学中)中性的，非酸非碱的","en":"In chemistry, neutral is used to describe things that are neither acid nor alkaline.","ex":{"en":"Pure water is neutral with a pH of 7.","cn":"纯水是中性的，酸碱度为7。"}}]},"examples":[{"en":"I didn't take my father's or my mother's side; I tried to remain neutral.","cn":"我既不支持父亲也不袒护母亲，尽力做到不偏不倚。"},{"en":"Journalists are supposed to be politically neutral.","cn":"新闻工作者在政治上应持中立态度。"}]},"nearby":{"media":{"uk":"media/uk/nearby__gb_1.mp3","us":"media/us/nearby__us_1.mp3"},"oxford":{"phon":"ˌnɪəˈbaɪ","pos":"adjective","senses":[{"en":"near in position; not far away","cn":"附近的；邻近的","ex":{"en":"Her mother lived in a nearby town.","cn":"她母亲住在附近一个小镇上。"}},{"en":"a short distance from somebody/something; not far away","cn":"在附近；不远","ex":{"en":"They live nearby.","cn":"他们住在附近。"},"pos":"adverb"}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"在附近;在近处","en":"If something is nearby, it is only a short distance away.","ex":{"en":"He might easily have been seen by someone who lived nearby","cn":"住在附近的人很可能有谁见过他。"}}]},"examples":[{"en":"Her mother lived in a nearby town.","cn":"她母亲住在附近一个小镇上。"},{"en":"There were complaints from nearby residents.","cn":"附近的居民有些怨言。"}]},"necessitate":{"oxford":{"phon":"nəˈsesɪteɪt","pos":"verb","senses":[{"en":"to make something necessary","cn":"使成为必要","ex":{"en":"Recent financial scandals have necessitated changes in parliamentary procedures.","cn":"最近的金融丑闻使得议会程序必须改革。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"使成为必需;需要","en":"If something necessitates an event, action, or situation, it makes it necessary.","ex":{"en":"A prolonged drought had necessitated the introduction of water rationing","cn":"由于持续干旱，用水需要实行配给了。"}}]},"media":{"uk":"media/uk/necessitate__gb_1.mp3","us":"media/us/necessitate__us_1.mp3"},"examples":[{"en":"Recent financial scandals have necessitated changes in parliamentary procedures.","cn":"最近的金融丑闻使得议会程序必须改革。"},{"en":"Increased traffic necessitated widening the road.","cn":"交通量增大，这就需要拓宽道路。"}]},"neighbors":{"oxford":{"phon":"ˈneɪbə(r)","pos":"noun","senses":[{"en":"a person who lives next to you or near you","cn":"邻居；邻人"},{"en":"a country that is next to or near another country","cn":"邻国"}]}},"neglect":{"media":{"uk":"media/uk/neglect__gb_1.mp3","us":"media/us/neglect__us_1.mp3"},"oxford":{"phon":"nɪˈɡlekt","pos":"verb","senses":[{"en":"to fail to take care of somebody/something","cn":"疏于照顾；未予看管","ex":{"en":"She denies neglecting her baby.","cn":"她不承认没有照看好她的孩子。"}},{"en":"to not give enough attention to something","cn":"忽略；忽视；不予重视","ex":{"en":"Dance has been neglected by television.","cn":"电视节目一向不重视舞蹈。"}},{"en":"to fail or forget to do something that you ought to do","cn":"疏忽；疏漏","lab":"formal","ex":{"en":"You neglected to mention the name of your previous employer.","cn":"你忘了提你前雇主的名字。"}},{"en":"the fact of not giving enough care or attention to something/somebody; the state of not receiving enough care or attention","cn":"忽略；忽视；未被重视","ex":{"en":"The buildings are crumbling from years of neglect.","cn":"由于多年无人维修，这些建筑物行将倒塌。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"忽视;忽略;疏于照看","en":"If you neglect someone or something, you fail to look after them properly.","ex":{"en":"The woman denied that she had neglected her child","cn":"那位女士否认疏于照管自己的孩子。"}},{"pos":"VERB 动词","cn":"不予重视;忽视","en":"If you neglect someone or something, you fail to give them the amount of attention that they deserve.","ex":{"en":"He'd given too much to his career, worked long hours, neglected her","cn":"他为事业付出太多，长时间地工作，忽视了她。"}},{"pos":"VERB 动词","cn":"疏忽;疏漏","en":"If you neglect to do something that you ought to do or neglect your duty, you fail to do it.","ex":{"en":"We often neglect to make proper use of our bodies","cn":"我们经常忘记该合理地使用我们的身体。"}},{"pos":"","cn":"","en":"benign neglect→see: ;"}]},"examples":[{"en":"The buildings are crumbling from years of neglect.","cn":"由于多年无人维修，这些建筑物行将倒塌。"},{"en":"The law imposes penalties for the neglect of children.","cn":"法律对疏于照管儿童有处罚措施。"}]},"network":{"media":{"uk":"media/uk/network__gb_1.mp3","us":"media/us/network__us_1.mp3"},"oxford":{"phon":"ˈnetwɜːk","pos":"noun","senses":[{"en":"a complicated system of roads, lines, tubes, nerves, etc. that are connected to each other and operate together","cn":"网络；网状系统","lab":"figurative","ex":{"en":"a rail/road/canal network","cn":"铁路网；公路网；运河网"}},{"en":"a closely connected group of people, companies, etc. that exchange information, etc.","cn":"关系网；人际网；相互关系（或配合）的系统","ex":{"en":"They have one of the most efficient distribution networks in Europe.","cn":"他们的分销网是欧洲最具效率的分销网之一。"}},{"en":"a number of computers and other devices that are connected together so that equipment and information can be shared","cn":"（互联）网络","lab":"computing","ex":{"en":"The office network allows users to share files and software, and to use a central printer.","cn":"办公室网络让用户共享文件和软件，并使用中央打印机。"}},{"en":"a group of radio or television stations in different places that are connected and that broadcast the same programmes at the same time","cn":"广播网；电视网","ex":{"en":"the four big US television networks","cn":"美国四大电视网"}},{"en":"to connect a number of computers and other devices together so that equipment and information can be shared","cn":"将…连接成网络","g":"[transitive, usually passive]","lab":"computing","ex":{"en":"networked computer systems","cn":"联网的计算机系统"},"pos":"verb"},{"en":"to broadcast a television or radio programme on stations in several different areas at the same time","cn":"联播","g":"[transitive, usually passive]","ex":{"en":"nationally networked TV","cn":"全国联网电视"},"pos":"verb"},{"en":"to try to meet and talk to people who may be useful to you in your work","cn":"建立工作关系","g":"[intransitive]","ex":{"en":"Conferences are a good place to network.","cn":"各种会议是建立联系的好地方。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"网状物;网状系统","en":"A network of lines, roads, veins, or other long thin things is a large number of them which cross each other or meet at many points.","ex":{"en":"...Strasbourg, with its rambling network of medieval streets","cn":"中世纪街道纵横交织的斯特拉斯堡"}},{"pos":"N-COUNT 可数名词","cn":"(人或机构组成的)网络","en":"A network of people or institutions is a large number of them that have a connection with each other and work together as a system.","ex":{"en":"Distribution of the food is going ahead using a network of local church people and other volunteers","cn":"食品正通过当地教会人士和其他志愿者形成的网络分发下去。"}},{"pos":"N-COUNT 可数名词","cn":"网络;联动系统","en":"A particular network is a system of things which are connected and which operate together. For example, a computer network consists of a number of computers that are part of the same system.","ex":{"en":"...a computer network with 154 terminals","cn":"有154个终端的计算机网络"}},{"pos":"N-COUNT 可数名词","cn":"广播网;电视网","en":"A radio or television network is a company or group of companies that broadcasts radio or television programmes throughout an area.","ex":{"en":"An American network says it has obtained the recordings.","cn":"美国一家广播网声称已经得到了那些录音材料。"}},{"pos":"VERB 动词","cn":"对(电视或广播节目)进行联播","en":"When a television or radio programme is networked, it is broadcast at the same time by several different television companies.","ex":{"en":"Lumsdon would like to see his programme sold and networked","cn":"拉姆斯敦希望看到自己的节目卖出，并进行联播。"}},{"pos":"VERB 动词","cn":"建立工作关系网;交际","en":"If you network, you try to meet new people who might be useful to you in your job.","ex":{"en":"In business, it is important to network with as many people as possible on a face to face basis.","cn":"在生意场上，通过与尽可能多的人面对面地打交道来建立工作关系很重要。"}}]},"examples":[{"en":"The office network allows users to share files and software, and to use a central printer.","cn":"办公室网络让用户共享文件和软件，并使用中央打印机。"},{"en":"Conferences are a good place to network.","cn":"各种会议是建立联系的好地方。"}]},"networking":{"oxford":{"phon":"ˈnetwɜːkɪŋ","pos":"noun","senses":[{"en":"a system of trying to meet and talk to other people who may be useful to you in your work","cn":"人际关系网"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"建立工作关系网","en":"Networking is the process of trying to meet new people who might be useful to you in your job, often through social activities.","ex":{"en":"If executives fail to exploit the opportunities of networking they risk being left behind.","cn":"如果高管们未能抓住机会建立关系网，他们就有落后的风险。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(计算机系统的)联网，网络化","en":"You can refer to the things associated with a computer system or the process of establishing such a system as networking .","ex":{"en":"Managers have learned to grapple with networking, artificial intelligence, computer-aided engineering and manufacturing.","cn":"经理们已经学会了如何应对联网、人工智能、计算机辅助工程和制造。"}}]},"media":{"uk":"media/uk/networking__gb_1.mp3","us":"media/us/networking__us_1.mp3"},"examples":[{"en":"I’m hoping to do some networking at the conference next week in London.","cn":"我希望下周在伦敦召开的会议上能结交一些同行。"}]},"neuroscience":{"oxford":{"phon":"ˈnjʊərəʊsaɪəns","pos":"noun","senses":[{"en":"the science that deals with the structure and function of the brain and the nervous system","cn":"神经科学"}]},"media":{"uk":"media/uk/neuroscience__gb_1.mp3","us":"media/us/neuroscience__us_1.mp3"}},"news":{"media":{"uk":"media/uk/news__gb_1.mp3","us":"media/us/news__us_1.mp3"},"oxford":{"phon":"njuːz","pos":"noun","senses":[{"en":"new information about something that has happened recently","cn":"消息；音信","lab":"informal","ex":{"en":"What's the latest news?","cn":"有什么最新消息吗？"}},{"en":"reports of recent events that appear in newspapers or on television, radio or the internet","cn":"新闻；时事","ex":{"en":"national/international/local news","cn":"国内／国际／地方新闻"}},{"en":"a regular television or radio broadcast of the latest news","cn":"（电视或广播中的）新闻报道","ex":{"en":"to listen to/watch the news","cn":"收听／收看新闻节目"}},{"en":"a person, thing or event that is considered to be interesting enough to be reported as news","cn":"新闻人物；新闻事件","ex":{"en":"Pop stars are always news.","cn":"流行音乐明星总是新闻人物。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"新闻;消息","en":"News is information about a recently changed situation or a recent event.","ex":{"en":"We waited and waited for news of him","cn":"我们左等右等，盼着他的消息。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"新闻广播;新闻报道","en":"News is information that is published in newspapers and broadcast on radio and television about recent events in the country or world or in a particular area of activity.","ex":{"en":"Foreign News is on Page 16","cn":"国外新闻在16版。"}},{"pos":"N-SING 单数名词","cn":"电视新闻;广播新闻","en":"The news is a television or radio broadcast which consists of information about recent events in the country or the world.","ex":{"en":"I heard all about the bombs on the news.","cn":"我从新闻广播里得知了关于炸弹的全部消息。"}},{"pos":"N-IN-NAMES 名称名词","cn":"(用于报纸名)新闻","en":"News is sometimes used in the names of newspapers.","ex":{"en":"...the New York Daily News.","cn":"《纽约每日新闻》"}},{"pos":"N-UNCOUNT 不可数名词","cn":"新闻人物;新闻事件","en":"If you say that someone or something is news, you mean that they are considered to be interesting and important at the moment, and that people want to hear about them on the radio and television and in newspapers.","ex":{"en":"A murder was big news","cn":"谋杀案是重大新闻事件。"}},{"pos":"PHRASE 短语","cn":"坏事/好事","en":"If you say that something is bad news, you mean that it will cause you trouble or problems. If you say that something is good news, you mean that it will be useful or helpful to you.","ex":{"en":"The drop in travel is bad news for the airline industry","cn":"旅游热降温对航空业来说是个坏消息。"}},{"pos":"PHRASE 短语","cn":"对(某人)来说是新闻","en":"If you say that something is news to you, you mean that you did not previously know what you have just been told, especially when you are surprised or annoyed about it.","ex":{"en":"I'd certainly tell you if I knew anything, but I don't. What you're saying is news to me.","cn":"如果我真知道什么的话，我肯定会告诉你，可我不知道。你现在说的我都没听过。"}}]},"examples":[{"en":"The cut in interest rates is good news for homeowners.","cn":"降低利率对于私房买主来说是个福音。"},{"en":"Messengers brought news that the battle had been lost.","cn":"通信员送来消息说这场战斗失败了。"}]},"neck":{"media":{"img":["media/pic/neck_comp.jpg","media/thumb/neck.jpg"],"uk":"media/uk/neck__gb_1.mp3","us":"media/us/neck__us_1.mp3"},"oxford":{"phon":"nek","pos":"noun","senses":[{"en":"the part of the body between the head and the shoulders","cn":"颈；脖子","g":"[countable]","lab":"informal","ex":{"en":"He tied a scarf around his neck.","cn":"他脖子上围着围巾。"}},{"en":"the part of a piece of clothing that fits around the neck","cn":"衣领；领子；领圈","g":"[countable]","ex":{"en":"He wore a casual shirt with an open neck.","cn":"他穿着一件开领的休闲衬衫。"}},{"en":"having the type of neck mentioned","cn":"有…衣领的；有…脖子的","ex":{"en":"a round-necked sweater","cn":"一件圆领毛衣"}},{"en":"a long narrow part of something","cn":"（物体的）细长部分，颈部","g":"[countable]","ex":{"en":"the neck of a bottle","cn":"瓶颈"}},{"en":"the neck of an animal, cooked and eaten","cn":"（烹制食用的）动物颈肉","g":"[uncountable]","ex":{"en":"neck of lamb","cn":"小羊颈肉"}},{"en":"when two people are necking, they are kissing each other in a sexual way","cn":"搂着脖子亲吻；相拥互吻","pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"颈;脖子","en":"Your neck is the part of your body which joins your head to the rest of your body.","ex":{"en":"She threw her arms round his neck and hugged him warmly","cn":"她伸出双臂搂住他的脖子，热情地拥抱他。"}},{"pos":"N-COUNT 可数名词","cn":"衣领;领口","en":"The neck of an article of clothing such as a shirt, dress, or sweater is the part which surrounds your neck.","ex":{"en":"...the low, ruffled neck of her blouse","cn":"她的打褶低胸的衬衫领口"}},{"pos":"N-COUNT 可数名词","cn":"(瓶子、吉他等的)颈状部位，细长部分，颈部","en":"The neck of something such as a bottle or a guitar is the long narrow part at one end of it.","ex":{"en":"Catherine gripped the broken neck of the bottle.","cn":"凯瑟琳紧握着破裂的瓶颈。"}},{"pos":"V-RECIP 相互动词","cn":"搂着脖子亲吻;相拥而吻","en":"If two people are necking, they are kissing each other in a sexual way.","ex":{"en":"They sat talking and necking in the car for another ten minutes","cn":"他们在车里又坐了10分钟，边说边搂着亲热。"}},{"pos":"N-SING 单数名词","cn":"(赛马)以微弱优势(获胜)，险(胜)","en":"If a horse wins a race by a neck, it wins by a very small distance.","ex":{"en":"Cee En Cee went on to win by a neck from Leigh Crofter.","cn":"西恩西再次以微弱优势战胜莉·克罗夫特。"}},{"pos":"PHRASE 短语","cn":"密切监视;紧紧盯住","en":"If you say that someone is breathing down your neck, you mean that they are watching you very closely and checking everything you do.","ex":{"en":"Most farmers have bank managers breathing down their necks.","cn":"大部分农场主的一举一动都受到银行经理们的密切关注。"}},{"pos":"PHRASE 短语","cn":"(尤指选举中)并驾齐驱，难分高低","en":"In a competition, especially an election, if two or more competitors are neck and neck, they are level with each other and have an equal chance of winning.","ex":{"en":"The latest polls indicate that the two main parties are neck and neck","cn":"最近的一次民意测验显示两个主要政党难分高下。"}},{"pos":"PHRASE 短语","cn":"(常指为实现某事)冒险","en":"If you say that someone is risking their neck, you mean they are doing something very dangerous, often in order to achieve something.","ex":{"en":"I won't have him risking his neck on that motorcycle.","cn":"我不会让他冒险骑那辆摩托车。"}},{"pos":"PHRASE 短语","cn":"保全(某人的工作或声誉)","en":"To save someone's neck means to prevent them from losing their job or harming their reputation.","ex":{"en":"He had enough friends in the right places to save his neck and cover up for him","cn":"他有很多朋友能保全他，帮他打掩护。"}},{"pos":"PHRASE 短语","cn":"担风险;找麻烦;惹祸","en":"If you stick your neck out, you bravely say or do something that might be criticized or might turn out to be wrong.","ex":{"en":"During my political life I've earned myself a reputation as someone who'll stick his neck out, a bit of a rebel.","cn":"我在政治生涯中敢冒风险、有点叛逆是小有名气的。"}},{"pos":"PHRASE 短语","cn":"担负;缠住","en":"If you say that you have something round your neck or around your neck, you mean that it is your responsibility and it causes you a lot of worry.","ex":{"en":"No-one should start working life with a debt round their neck","cn":"任何人都不该身背债务开始工作生涯。"}},{"pos":"PHRASE 短语","cn":"深深陷入，被卷入(麻烦、罪行等)","en":"If you say that someone is in some sort of trouble or criminal activity up to their neck, you mean that they are deeply involved in it.","ex":{"en":"The black market was flourishing, everybody was corrupt, in it up to their necks","cn":"黑市繁荣，每个人都已堕落，深陷其中。"}},{"pos":"PHRASE 短语","cn":"地段;附近地区","en":"Someone or something that is from your neck of the woods is from the same part of the country as you are.","ex":{"en":"It's so good to see you. What brings you to this neck of the woods?","cn":"见到你真高兴，哪阵风把你吹来了？"}},{"pos":"","cn":"","en":"to have a millstone round your neck→see: ; the scruff of your neck→see: ;"}]},"examples":[{"en":"She craned (= stretched) her neck to get a better view.","cn":"她伸长了脖子，想看得清楚一点。"},{"en":"Somebody's going to break their neck (= injure themselves) on these steps.","cn":"会有人在这台阶上摔伤的。"}]},"neatly":{"oxford":{"phon":"ˈniːtli","pos":"adverb","senses":[{"en":"in a way that is tidy and in order; carefully","cn":"整齐有序地","ex":{"en":"neatly folded clothes","cn":"叠得整整齐齐的衣服"}},{"en":"in a simple but clever way","cn":"简洁的；睿智的；灵巧的","ex":{"en":"She summarized her plan very neatly.","cn":"她简洁地总结了她的计划。"}}]},"media":{"uk":"media/uk/neatly__gb_1.mp3","us":"media/us/neatly__us_1.mp3"},"examples":[{"en":"She summarized her plan very neatly.","cn":"她非常简明地总结了她的计划。"},{"en":"The box fitted neatly into the drawer.","cn":"这盒子放在抽屉里正合适。"}]},"ne":{"oxford":{"phon":"","pos":"abbreviation","senses":[{"en":"north-east; north-eastern","cn":"东北方（的）；东北部（的）","ex":{"en":"NE England","cn":"英格兰东北部"}}]},"media":{"us":"media/ldoce/hwd/ame/2/ne_che.mp3"},"examples":[{"en":"NE England","cn":"英格兰东北部"}],"collins":{"senses":[{"pos":"","cn":"","en":"NE is a written abbreviation for (书面缩略=) north-east .","ex":{"en":"...on the NE outskirts of Bath.","cn":"在巴斯东北郊区"}}]}},"negative":{"media":{"uk":"media/uk/negative__gb_1.mp3","us":"media/us/negative__us_1.mp3"},"oxford":{"phon":"ˈneɡətɪv","pos":"adjective","senses":[{"en":"bad or harmful","cn":"坏的；有害的","sc":"bad","ex":{"en":"The crisis had a negative effect on trade.","cn":"这次危机对贸易产生了不良影响。"}},{"en":"containing a word such as ‘no’, ‘not’, ‘never’, etc.","cn":"含有否定词的；否定的","sc":"grammar","ex":{"en":"a negative form/sentence","cn":"否定形式／句"}},{"en":"expressing the answer ‘no’","cn":"否定的","sc":"no","ex":{"en":"His response was negative.","cn":"他的回答是否定的。"}},{"en":"considering only the bad side of something/somebody; having no enthusiasm or hope","cn":"消极的；悲观的；缺乏热情的","sc":"not hopeful","ex":{"en":"Scientists have a fairly negative attitude to the theory.","cn":"科学家对这个理论的态度是相当消极的。"}},{"en":"not showing any evidence of a particular substance or medical condition","cn":"结果为阴性的（或否定的）","sc":"scientific test","ex":{"en":"Her pregnancy test was negative.","cn":"她的孕检呈阴性。"}},{"en":"containing or producing the type of electricity that is carried by an electron","cn":"负极的；阴极的","lab":"specialist","sc":"electricity","ex":{"en":"a negative charge/current","cn":"负电荷；负电流"}},{"en":"less than zero","cn":"负的；小于零的","sc":"number/quantity","ex":{"en":"a negative trade balance","cn":"贸易逆差"}},{"en":"showing light and shade, or colours, in the opposite way to the original","cn":"底片的；负片的","sc":"image","ex":{"en":"In a negative image of the photograph, dark is light and right is left.","cn":"相片的底片中，光暗和左右都倒转了。"}},{"en":"a word or statement that means ‘no’; an act of refusing to do something or of denying something","cn":"否定词；否定；拒绝","lab":"formal","sc":"no","ex":{"en":"She answered in the negative (= said ‘no’).","cn":"她作了否定的回答。"},"pos":"noun"},{"en":"a bad quality or aspect of a situation","cn":"坏的一面","sc":"bad quality","ex":{"en":"Try not to focus on the negative.","cn":"尽量不要只看坏的一面。"},"pos":"noun"},{"en":"the result of a test or an experiment that shows that a substance or condition is not present","cn":"属阴性（或否定）的结果","sc":"in scientific test","ex":{"en":"The percentage of false negatives generated by the cancer test is of great concern.","cn":"癌症检查的结果中，假阴性占一定比例的现象受到极大关注。"},"pos":"noun"},{"en":"a word such as ‘no’, ‘not’, ‘never’, etc.","cn":"否定词","sc":"grammar","ex":{"en":"Double negatives, as in ‘I don't want no dinner’, are considered an error in English.","cn":"双重否定，如“我不想吃晚饭”，在英语中被认为是错误的。"},"pos":"noun"},{"en":"a developed film showing the dark areas of an actual scene as light and the light areas as dark","cn":"负片；底片","sc":"in photography","ex":{"en":"Keep the negatives in case you want more prints later.","cn":"保留底片，以备日后需要更多冲印时使用。"},"pos":"noun"},{"en":"to refuse to agree to a proposal or a request","cn":"拒绝；否定","pos":"verb"},{"en":"to prove that something is not true","cn":"否定…的真实性；证伪","pos":"verb"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(事实、局势或经历)不悦的，沮丧的，有害的","en":"A fact, situation, or experience that is negative is unpleasant, depressing, or harmful.","ex":{"en":"The news from overseas is overwhelmingly negative","cn":"来自海外的消息特别不容乐观。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"消极的;悲观的","en":"If someone is negative or has a negative attitude, they consider only the bad aspects of a situation, rather than the good ones.","ex":{"en":"When asked for your views about your current job, on no account must you be negative about it","cn":"被问及你对自己目前工作的看法时，无论如何不要流露出消极情绪。"}},{"pos":"ADJ 形容词","cn":"(回答或决定)否定的，表示否认的","en":"A negative reply or decision indicates the answer 'no'.","ex":{"en":"Dr Velayati gave a vague but negative response","cn":"韦拉亚提医生给了一个含糊而否定的回答。"}},{"pos":"N-COUNT 可数名词","cn":"否定词;否定语;否定表示","en":"A negative is a word, expression, or gesture that means 'no' or 'not'.","ex":{"en":"In the past we have heard only negatives when it came to following a healthy diet.","cn":"说到遵循健康饮食习惯，我们过去听到的都是否定的说法。"}},{"pos":"ADJ 形容词","cn":"(语法中)否定句的，否定式的","en":"In grammar, a negative clause contains a word such as 'not', 'never', or 'no-one'."},{"pos":"ADJ 形容词","cn":"(医学检查或科学试验)呈阴性的，结果为否定的","en":"If a medical test or scientific test is negative, it shows no evidence of the medical condition or substance that you are looking for.","ex":{"en":"So far 57 have taken the test and all have been negative.","cn":"到目前为止，参加测试的有57人，测试结果均呈阴性。"}},{"pos":"","cn":"","en":"HIV negative→see: ;"},{"pos":"N-COUNT 可数名词","cn":"(摄影的)负片，底片","en":"In photography, a negative is an image that shows dark areas as light and light areas as dark. Negatives are made from a camera film, and are used to print photographs."},{"pos":"ADJ 形容词","cn":"负的;负极的","en":"A negative charge or current has the same electrical charge as an electron.","ex":{"en":"Stimulate the site of greatest pain with a small negative current.","cn":"以微弱负电流刺激疼得最厉害的部位。"}},{"pos":"ADJ 形容词","cn":"(数字、数量等)小于零的，负的","en":"A negative number, quantity, or measurement is less than zero.","ex":{"en":"The weakest students can end up with a negative score.","cn":"最差的学生可能会以负分收场。"}},{"pos":"PHRASE 短语","cn":"(指回答)否定的，否定地","en":"If an answer is in the negative, it is 'no' or means 'no'.","ex":{"en":"The Council answered those questions in the negative","cn":"委员会对那些问题的答复是否定的。"}},{"pos":"PHRASE 短语","cn":"否定句的;否定式的","en":"If a sentence is in the negative, it contains a word such as 'not', 'never', or 'no-one'.","ex":{"en":"'I went' in the negative is 'I did not go'.","cn":"I went (我去了)的否定式是 I did not go (我没去)。"}}]},"examples":[{"en":"The percentage of false negatives generated by the cancer test is of great concern.","cn":"癌症检查的结果中，假阴性占一定比例的现象受到极大关注。"},{"en":"‘He probably won't show up.’ ‘Don't be so negative.’ “","cn":"他很可能不会露面。” “别那么泄气嘛。”"}]},"nervous":{"media":{"uk":"media/uk/nervous__gb_1.mp3","us":"media/us/nervous__us_1.mp3"},"oxford":{"phon":"ˈnɜːvəs","pos":"adjective","senses":[{"en":"anxious about something or afraid of something","cn":"焦虑的；担忧的；惶恐的","ex":{"en":"I felt really nervous before the interview.","cn":"面试前我感到惶恐不安。"}},{"en":"easily worried or frightened","cn":"神经质的；易紧张焦虑的；胆怯的","ex":{"en":"She was a thin, nervous girl.","cn":"她是个瘦削而又胆怯的女孩儿。"}},{"en":"connected with the body’s nerves and often affecting you mentally or emotionally","cn":"神经系统的","ex":{"en":"a nervous condition/disorder/disease","cn":"神经系统疾病；神经紊乱；神经症"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"神经紧张的;担忧的;焦虑的","en":"If someone is nervous, they are frightened or worried about something that is happening or might happen, and show this in their behaviour.","ex":{"en":"The party has become deeply nervous about its prospects of winning the next election","cn":"该党对赢得下一次选举的前景深感忧虑。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"神经质的;神经过敏的","en":"A nervous person is very tense and easily upset.","ex":{"en":"She was apparently a very nervous woman, and that affected her career.","cn":"她显然是一个很神经质的女人，这一点影响了她的事业。"}},{"pos":"ADJ 形容词","cn":"神经性的;神经的","en":"A nervous illness or condition is one that affects your emotions and your mental state.","ex":{"en":"The number of nervous disorders was rising in the region","cn":"该地区神经紊乱患者的人数在上升。"}}]},"examples":[{"en":"All this talk of job losses was making him jittery.","cn":"所有这些关于失业的话题使他心神不宁。"},{"en":"By the time the police arrived, I was a nervous wreck.","cn":"警察到达时，我已经紧张得不行了。"}]},"neglected":{"oxford":{"phon":"nɪˈɡlektɪd","pos":"adjective","senses":[{"en":"not receiving enough care or attention","cn":"被忽略的；被忽视的；未被重视的","ex":{"en":"neglected children","cn":"无人照看的孩子"}}]},"media":{"uk":"media/uk/neglected__gb_1.mp3","us":"media/us/neglected__us_1.mp3"},"examples":[{"en":"a neglected area of research","cn":"被人忽略了的研究领域"},{"en":"neglected children","cn":"无人照看的孩子"}]},"negligence":{"media":{"uk":"media/uk/negligence__gb_1.mp3","us":"media/us/negligence__us_1.mp3"},"oxford":{"phon":"ˈneɡlɪdʒəns","pos":"noun","senses":[{"en":"the failure to give somebody/something enough care or attention","cn":"疏忽；失职；失误；过失","ex":{"en":"The accident was caused by negligence on the part of the driver.","cn":"事故是由司机的过失造成的。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"疏忽;失误;失职","en":"If someone is guilty of negligence, they have failed to do something which they ought to do.","ex":{"en":"The soldiers were ordered to appear before a disciplinary council on charges of negligence.","cn":"士兵们被控玩忽职守，被勒令接受纪律委员会的审查。"}}]},"examples":[{"en":"The doctor was sued for medical negligence.","cn":"这名医生因为引致医疗事故而被起诉。"},{"en":"The accident was caused by negligence on the part of the driver.","cn":"事故是由于司机的过失造成的。"}]},"newly":{"media":{"uk":"media/uk/newly__gb_1.mp3","us":"media/us/newly__us_1.mp3"},"oxford":{"phon":"ˈnjuːli","pos":"adverb","senses":[{"en":"recently","cn":"最近；新近","ex":{"en":"a newly qualified doctor","cn":"新近获得行医许可的医生"}}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"(置于过去分词或形容词前)新近，最近","en":"Newly is used before a past participle or an adjective to indicate that a particular action is very recent, or that a particular state of affairs has very recently begun to exist.","ex":{"en":"She was young at the time, and newly married.","cn":"她那时年龄不大，刚结婚。"}}]},"examples":[{"en":"a newly qualified doctor","cn":"新近获得行医许可的医生"},{"en":"a newly independent republic","cn":"刚独立的共和国"}]},"neighborhood":{"oxford":{"phon":"ˈneɪbəhʊd","pos":"noun","senses":[{"en":"a district or an area of a town; the people who live there","cn":"街区；城区；（统称）某街区（或城区）的居民"},{"en":"the area that you are in or the area near a particular place","cn":"所在地；邻近的地方"}]}},"networks":{"oxford":{"phon":"ˈnetwɜːk","pos":"noun","senses":[{"en":"a complicated system of roads, lines, tubes, nerves, etc. that cross each other and are connected to each other","cn":"网络；网状系统"},{"en":"a closely connected group of people, companies, etc. that exchange information, etc.","cn":"关系网；人际网；相互关系（或配合）的系统"}]}},"nearest":{"oxford":{"phon":"nɪə(r)","pos":"adjective","senses":[{"en":"a short distance away","cn":"距离近；不远"},{"en":"a short time away in the future","cn":"不久以后"}]}},"neighbours":{"oxford":{"phon":"ˈneɪbəz","pos":"","senses":[{"en":"an Australian soap opera that became very popular in Britain. It is about the lives and relationships of the people living on an imaginary street in Melbourne.","cn":"邻居：澳大利亚的肥皂剧在英国很受欢迎。这是关于生活在墨尔本假想街道上的人们的生活和人际关系。"}]},"media":{"uk":"media/ldoce/hwd/bre/f/ld5_neighbours.mp3","us":"media/ldoce/hwd/ame/f/ld5_neighbours.mp3"}},"needed":{"oxford":{"phon":"niːd","pos":"verb","senses":[{"en":"to require sth/sb because they are essential or very important, not just because you would like to have them","cn":"需要；必需"},{"en":"used to show what you should or have to do （","cn":"表示应该或不得不做）有必要"}]}},"newspaperman":{"oxford":{"phon":"ˈnjuːzpeɪpəmæn","pos":"noun","senses":[{"en":"a male journalist who works for a newspaper","cn":"报社记者"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(尤指男)新闻记者，报社记者","en":"A newspaperman is a journalist, especially a man, who works for a newspaper."}]},"media":{"uk":"media/ldoce/hwd/bre/6/ld41newspaperman.mp3","us":"media/ldoce/hwd/ame/9/laadnewspaperman.mp3"}},"newspapers":{"oxford":{"phon":"ˈnjuːzpeɪpə(r)","pos":"noun","senses":[{"en":"a set of large printed sheets of paper containing news, articles, advertisements, etc. and published every day or every week","cn":"报纸；报"},{"en":"paper taken from old newspapers","cn":"旧报纸"}]}},"neighbor":{"oxford":{"phon":"ˈneɪbə(r)","pos":"noun","senses":[{"en":"a person who lives next to you or near you","cn":"邻居；邻人"},{"en":"a country that is next to or near another country","cn":"邻国"}]}},"neighboring":{"oxford":{"phon":"ˈneɪbərɪŋ","pos":"adj.","senses":[{"en":"located or living near or next to a place or person","cn":"邻近的；附近的；毗邻的"}]}},"nerves":{"oxford":{"phon":"nɜːv","pos":"noun","senses":[{"en":"any of the long threads that carry messages between the brain and parts of the body, enabling you to move, feel pain, etc.","cn":"神经"},{"en":"feelings of worry or anxiety","cn":"神经质；神经紧张"}]}},"newsstand":{"oxford":{"phon":"","pos":"noun","senses":[{"en":"a place on the street, at a station, etc. where you can buy newspapers and magazines","cn":"报摊；书报亭"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"报摊;售报亭","en":"A newsstand is a stall in the street or a public place, which sells newspapers and magazines.","ex":{"en":"Eight new national newspapers have appeared on the newsstands since 1981.","cn":"自1981年以来，8种新的全国性报纸出现在报摊上。"}}]},"media":{"uk":"media/ldoce/hwd/bre/f/newsstand0205.mp3","us":"media/ldoce/hwd/ame/d/ld41newsstand.mp3"}},"newcomers":{"oxford":{"phon":"ˈnjuːkʌmə(r)","pos":"noun","senses":[{"en":"a person who has only recently arrived in a place or started an activity","cn":"新来者；新手"}]}},"negligent":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"疏忽的;玩忽职守的;失职的","en":"If someone in a position of responsibility is negligent, they do not do something which they ought to do.","ex":{"en":"The jury determined that the airline was negligent in training and supervising the crew","cn":"陪审团裁定航空公司在对全体机组人员的培训和管理问题上存在疏漏。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"随便的;放松的;不修边幅的","en":"If you describe a person's movements or manner as negligent, you mean that they look relaxed and informal.","ex":{"en":"Laura acknowledged this compliment with a negligent wave of her left hand","cn":"劳拉随意挥了挥左手算是听到了这个赞扬。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not paying enough attention to what you are doing, so that you make mistakes, damage things etc","cn":""},{"en":"often dropping or breaking things because you move around in a careless way","cn":""},{"en":"careless and lazy in the way you do your work or in your behaviour generally","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Use negligent when you want to describe someone who just doesn't give a hoot. You can be negligent at work if you let the work pile up while you play computer games, or you can be negligent at home if you haven't fed your fish for six days straight."}]},"collocations":{"phrases":["VERBS be, seem","ADV. extremely, grossly, seriously, very | wholly | criminally","PREP. in The hospital was negligent in the way it looked after this young man. | over The court found him to be negligent over the loss of &"]},"media":{"uk":"media/ldoce/hwd/bre/d/negligent0205.mp3","us":"media/ldoce/hwd/ame/e/ld41negligent.mp3"},"examples":[{"en":"The school had been negligent in not informing the child's parents about the incident.","cn":"校方疏忽了，没有向这孩子的父母通报这件事。"},{"en":"The defendant drove negligently and hit a lamp post.","cn":"被告不小心驾驶，撞到一根路灯柱上了。"}],"oxford":{"phon":"ˈneɡlɪdʒənt","pos":"adjective","senses":[{"en":"failing to give somebody/something enough care or attention, especially when this has serious results","cn":"疏忽的；造成过失的","lab":"law or formal","ex":{"en":"The company was found to have been grossly negligent.","cn":"该公司被发现存在严重疏忽。"}},{"en":"relaxed; not formal","cn":"放松的；随便的","lab":"literary","ex":{"en":"He waved his hand in a negligent gesture.","cn":"他漫不经心地挥了挥手。"}}]}},"negligible":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"微不足道的;可忽略不计的","en":"An amount or effect that is negligible is so small that it is not worth considering or worrying about.","ex":{"en":"The pay that the soldiers received was negligible","cn":"士兵拿到的军饷少得可怜。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not important","cn":""},{"en":"not important, or not very important. These phrases sound a little more formal than unimportant","cn":""},{"en":"small and not very likely to have an important effect – used especially about changes, problems, injuries, damage, or differences","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"When something is meaningless or insignificant because it is so little, it's negligible . The amount of interest you'll get on your savings is negligible , so you might as well spend your money."}]},"collocations":{"phrases":["VERBS be, seem | become","ADV. absolutely | by no means, far from Delays in the courts are far from negligible. | almost"]},"media":{"uk":"media/ldoce/hwd/bre/7/negligible0205.mp3","us":"media/ldoce/hwd/ame/c/ld41negligible.mp3"},"examples":[{"en":"The cost was negligible.","cn":"费用不大，无关紧要。"},{"en":"a negligible amount","cn":"很小的量"}],"oxford":{"phon":"ˈneɡlɪdʒəbl","pos":"adjective","senses":[{"en":"of very little importance or size and not worth considering","cn":"微不足道的；不重要的；不值一提的","ex":{"en":"The cost was negligible.","cn":"费用不大，无关紧要。"}}]}},"nettle":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"荨麻","en":"Nettles are wild plants which have leaves covered with fine hairs that sting you when you touch them.","ex":{"en":"The nettles stung their legs.","cn":"荨麻扎了他们的腿。"}},{"pos":"VERB 动词","cn":"惹恼;冒犯","en":"If you are nettled by something, you are annoyed or offended by it.","ex":{"en":"He was nettled by her manner","cn":"她的举止惹恼了他。"}},{"pos":"PHRASE 短语","cn":"迎难而上;知难而进;大胆抓棘手问题","en":"If you grasp the nettle, you deal with a problem, or do something that is unpleasant, quickly and in a determined way.","ex":{"en":"Some industrialists believe the government should grasp the nettle of devaluation before the referendum takes place.","cn":"一些实业家认为政府应该在全民公决前果断出手解决棘手的货币贬值问题。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a wild plant with rough leaves that sting you","cn":"荨麻"},{"en":"to be annoyed by what someone says or does","cn":"被（某事物）惹怒"}]},"vocab":{"pos":"n v","senses":[{"en":"If you know what a nettle is—that is, a barbed seed that gets stuck in your clothes and hair—then you'll have no trouble remembering the verb nettle : it means to annoy, bother, irritate, or bedevil."}]},"collocations":{"phrases":["ADJ. stinging | dead (= a variety that does not sting)","QUANT. clump, patch","VERB + NETTLE cut (down), get rid of","NETTLE + VERB grow | sting | spread The nettles had spread and now covered half the garden.","PREP. in (the) ~s There was an old car half buried in the nettles. | on ~s The butterflies lay their eggs on nettles."]},"media":{"uk":"media/ldoce/hwd/bre/1/ld41nettle.mp3","us":"media/ldoce/hwd/ame/1/ld41nettle.mp3","img":["media/thumb/nettle.jpg"]},"examples":[{"en":"My remarks clearly nettled her.","cn":"我的话显然惹恼了她。"},{"en":"She was nettled by Holman’s remark.","cn":"她被霍尔曼的话激怒了。"}],"oxford":{"phon":"ˈnetl","pos":"noun","senses":[{"en":"a wild plant with leaves that have pointed edges, are covered in fine hairs and sting (= cause you pain) if you touch them","cn":"荨麻","ex":{"en":"The nettles had spread and now covered half the garden.","cn":"荨麻向四周曼延，已经遍及半个花园了。"}},{"en":"to make somebody slightly angry","cn":"使恼怒；使生气","ex":{"en":"My remarks clearly nettled her.","cn":"我的话显然惹恼了她。"},"pos":"verb"}]}},"negotiator":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"谈判人;协商者","en":"Negotiators are people who take part in political or financial negotiations.","ex":{"en":"...the rebels' chief negotiator at the peace talks","cn":"和谈中叛乱分子的首席谈判代表"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who takes part in official discussions, especially in business or politics, in order to try and reach an agreement 〔","cn":"尤指商业或政治方面的〕谈判代表﹐协商者"}]},"collocations":{"phrases":["ADJ. clever, good, skilled, tough | professional, trained | chief, principal, senior the trade union's chief negotiator | union • Note at JO"]},"media":{"uk":"media/ldoce/hwd/bre/3/ld41negotiator.mp3","us":"media/ldoce/hwd/ame/3/ld41negotiator.mp3"},"examples":[{"en":"the chief union negotiator","cn":"工会的首席谈判代表"}],"oxford":{"phon":"nɪˈɡəʊʃieɪtə(r)","pos":"noun","senses":[{"en":"a person who is involved in formal discussions between people who are trying to reach an agreement, especially as part of their job","cn":"谈判代表；协商者","ex":{"en":"the union’s chief negotiator","cn":"工会的首席谈判代表"}}]}},"nestle":{"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"(使)(舒适地)安顿下来，安卧，偎依","en":"If you nestle or are nestled somewhere, you move into a comfortable position, usually by pressing against someone or against something soft.","ex":{"en":"John took one child into the crook of each arm and let them nestle against him","cn":"约翰一只臂弯搂着一个孩子，让他们舒服地靠着他。"}},{"pos":"V-ERG 及物/不及物动词","cn":"(使)置于，坐落在(安全、有遮蔽之处)","en":"If something such as a building nestles somewhere or if it is nestled somewhere, it is in that place and seems safe or sheltered.","ex":{"en":"Nearby, nestling in the hills, was the children's home","cn":"孩子们的家就在附近的山里。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to move into a comfortable position, pressing your head or body against someone or against something soft （","cn":"使）舒适地安顿下来﹔（使）偎依﹐（使）依靠"},{"en":"to be surrounded by something, especially hills or countryside","cn":"坐落在〔尤指山间或乡间〕"}]},"vocab":{"pos":"v n","senses":[{"en":"To nestle into something is to get snug, comfy, and warm in it. You might nestle into your mother’s shoulder, or into a pile of blankets on the couch."}]},"collocations":{"phrases":["ADV. comfortably, safely","PREP. against She sat back, nestling against his chest. | among The town nestles comfortably among the hills. | between, in a tiny village n"]},"media":{"uk":"media/ldoce/hwd/bre/0/nestle0205.mp3","us":"media/ldoce/hwd/ame/7/ld41nestle.mp3"},"examples":[{"en":"He hugged her and she nestled against his chest.","cn":"他拥抱着她，她则依偎在他的怀里。"},{"en":"The little town nestles snugly at the foot of the hill.","cn":"这个小镇偎依在小山脚下。"}],"oxford":{"phon":"ˈnesl","pos":"verb","senses":[{"en":"to sit or lie down in a warm or soft place","cn":"依偎；舒适地坐（或卧）","g":"[intransitive]","ex":{"en":"He hugged her and she nestled against his chest.","cn":"他拥抱着她，她则依偎在他的怀里。"}},{"en":"to put or hold somebody/something in a comfortable position in a warm or soft place","cn":"抱；安置","g":"[transitive]","ex":{"en":"He nestled the baby in his arms.","cn":"他怀里抱着孩子。"}},{"en":"to be located in a position that is protected, sheltered or partly hidden","cn":"位处，坐落（于安全、隐蔽之处）","g":"[intransitive]","ex":{"en":"The little town nestles snugly at the foot of the hill.","cn":"这个小镇偎依在小山脚下。"}},{"en":"a large international company based in Switzerland that produces many types of food and drink, including Nescafé, powdered milk and many popular makes of chocolate. Since the 1980s there have been protests about the way the company sells powdered milk for babies in poor countries.","cn":"雀巢：总部位于瑞士的大型国际公司，生产多种食品和饮料，包括雀巢咖啡，奶粉和许多流行的巧克力。自1980年代以来，一直有人抗议该公司向贫穷国家的婴儿出售奶粉的方式。","pos":""}]}},"negotiate":{"collins":{"senses":[{"pos":"V-RECIP 相互动词","cn":"谈判;协商;洽谈","en":"If people negotiate with each other or negotiate an agreement, they talk about a problem or a situation such as a business arrangement in order to solve the problem or complete the arrangement.","ex":{"en":"It is not clear whether the president is willing to negotiate with the democrats","cn":"还不清楚总统是否愿意和民主人士洽谈。"}},{"pos":"VERB 动词","cn":"顺利通过;成功越过","en":"If you negotiate an area of land, a place, or an obstacle, you successfully travel across it or around it.","ex":{"en":"Frank Mariano negotiates the desert terrain in his battered pickup","cn":"弗兰克·马里亚诺驾驶他那辆破烂不堪的皮卡车成功穿越了沙漠地带。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to discuss a political problem or business arrangement in order to try to reach an agreement - use this especially about political or business leaders","cn":""},{"en":"a discussion in politics or business during which each group tries to gain for themselves as many advantages as possible but has to give something or do something in return","cn":""},{"en":"to discuss the details of a problem or plan thoroughly and argue about them until an agreement is reached","cn":""}]},"vocab":{"pos":"1 v 2 v","senses":[{"en":"To negotiate is to try to work out an agreement between parties that each want something out of the deal. You might negotiate with your mom — offering to do more chores for a raise in your allowance. Good luck."}]},"collocations":{"phrases":["ADV. carefully a carefully negotiated series of concessions | successfully | freely | individually, separately Rents are individually negoti","VERB + NEGOTIATE be able to | be prepared to, be willing to Are the employers really willing to negotiate? | attempt to, seek to, try to | m","PREP. between to negotiate between the two sides | for We are negotiating for the release of the prisoners. | on They have refused to negoti","ADV. easily, safely He safely negotiated the slippery stepping stones.","VERB + NEGOTIATE be difficult to The flight of steps was quite difficult to negotiate with a heavy suitcase."]},"media":{"uk":"media/ldoce/hwd/bre/7/negotiate0205.mp3","us":"media/ldoce/hwd/ame/6/ld41negotiate.mp3"},"examples":[{"en":"We successfully negotiated the release of the hostages.","cn":"我们成功地达成了释放人质的协议。"},{"en":"We have been negotiating for more pay.","cn":"我们一直在为增加工资进行协商。"}],"oxford":{"phon":"nɪˈɡəʊʃieɪt","pos":"verb","senses":[{"en":"to try to reach an agreement by formal discussion","cn":"谈判；磋商；协商","g":"[intransitive]","ex":{"en":"The government will not negotiate with terrorists.","cn":"政府不会和恐怖分子谈判。"}},{"en":"to arrange or agree something by formal discussion","cn":"商定，达成（协议）","g":"[transitive]","ex":{"en":"to negotiate a deal/contract/treaty/settlement","cn":"达成交易；确立合同；商定条约内容／解决措施"}},{"en":"to successfully get over or past a difficult part on a path or route","cn":"通过，越过（险要路段）","g":"[transitive]","lab":"formal","ex":{"en":"The climbers had to negotiate a steep rock face.","cn":"攀登者必须攀越陡峭的岩壁。"}}]}},"nerve":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"神经","en":"Nerves are long thin fibres that transmit messages between your brain and other parts of your body.","ex":{"en":"...spinal nerves.","cn":"脊神经"}},{"pos":"N-PLURAL 复数名词","cn":"承受力;意志力","en":"If you refer to someone's nerves, you mean their ability to cope with problems such as stress, worry, and danger.","ex":{"en":"Jill's nerves are stretched to breaking point","cn":"吉尔的神经绷紧到了极点。"}},{"pos":"N-PLURAL 复数名词","cn":"神经紧张;情绪不安","en":"You can refer to someone's feelings of anxiety or tension as nerves .","ex":{"en":"I just played badly. It wasn't nerves.","cn":"我只是打得很糟，不是紧张造成的。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"勇气;胆量;气魄","en":"Nerve is the courage that you need in order to do something difficult or dangerous.","ex":{"en":"The brandy made him choke, but it restored his nerve","cn":"虽说白兰地呛了他一下，却让他恢复了勇气。"}},{"pos":"VERB 动词","cn":"使鼓起勇气;使振作精神","en":"If you nerve yourself to do something difficult or frightening, you prepare yourself for it by trying to be brave.","ex":{"en":"I nerved myself to face the pain.","cn":"我鼓足勇气去面对痛苦。"}},{"pos":"PHRASE 短语","cn":"使…烦恼;使…心烦","en":"If someone or something gets on your nerves, they annoy or irritate you.","ex":{"en":"Lately he's not done a bloody thing and it's getting on my nerves.","cn":"近来他没有干任何坏事，这让我心神不定起来。"}},{"pos":"PHRASE 短语","cn":"胆敢;竟敢;厚颜","en":"If you say that someone has a nerve or has the nerve to do something, you are criticizing them for doing something which you feel they had no right to do.","ex":{"en":"They've got a nerve, complaining about our behaviour","cn":"他们竟敢对我们的行为表示不满。"}},{"pos":"PHRASE 短语","cn":"保持镇静;坚定不移","en":"If you hold your nerve or keep your nerve, you remain calm and determined in a difficult situation.","ex":{"en":"He held his nerve to beat Andre Agassi in a five-set thriller on Court One","cn":"他镇定自若，在1号场地惊心动魄的5盘3胜对决中击败了安德鲁·阿加西。"}},{"pos":"PHRASE 短语","cn":"紧张不安地度日;神经紧张","en":"If someone is living on their nerves, they are continually worried and anxious about the situation that they are in.","ex":{"en":"Eileen, mother of three, had been living on her nerves for some considerable time.","cn":"艾琳是3个孩子的母亲，已有相当一段时间总是感到紧张不安。"}},{"pos":"PHRASE 短语","cn":"失去勇气;变得胆怯;惊慌失措","en":"If you lose your nerve, you suddenly panic and become too afraid to do something that you were about to do.","ex":{"en":"The bomber had lost his nerve and fled.","cn":"放炸弹的人没了胆子，逃之夭夭。"}},{"pos":"PHRASE 短语","cn":"触及痛处;触及要害","en":"If you say that you have touched a nerve or touched a raw nerve, you mean that you have accidentally upset someone by talking about something that they feel strongly about or are very sensitive about.","ex":{"en":"Alistair saw Henry shrink, as if the words had touched a nerve","cn":"阿利斯泰尔看到亨利向后缩了一下，好像那些话触到了他的痛处。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the ability to behave bravely when you are in danger, suffering illness, or pain, or when other people are opposing you","cn":""},{"en":"the ability to behave bravely in a dangerous situation, for example during a war","cn":""},{"en":"the ability and determination to do something difficult or dangerous that other people are afraid to do","cn":""}]},"vocab":{"pos":"1 n 2 n v","senses":[{"en":"A nerve is a group of fibers that send sensation or physical feeling to the brain. Back pain can sometimes be caused by a damaged or pinched nerve ."}]},"collocations":{"phrases":["ADJ. sensitive, trapped | facial, optic, spinal, etc.","VERB + NERVE damage, strain, trap I've trapped a nerve in my spine.","NERVE + VERB go, lead, run The nerve runs from the eye to the brain. | transmit sth The nerves transmit pain. | throb He lay awake, his nerv","NERVE + NOUN cell, end, ending, fibre, tissue | pathway | impulse | damage, injury | gas","PREP. along a/the ~ The message travels along the nerve to the brain. | ~ in He's been off work with a trapped nerve in his back. | ~ to Cut","PHRASES every nerve in sb's body Intense pain shot through every nerve in his body. | hit a nerve, touch a (sensitive/raw) nerve (figurative","ADJ. good, steady | bad, frayed, ragged, shattered, taut At the end of a day's teaching, her nerves were absolutely shattered.","VERB + NERVE stretch Her nerves were stretched to breaking point."]},"media":{"uk":"media/ldoce/hwd/bre/b/nerve_las2_br.mp3","us":"media/ldoce/hwd/ame/9/ld41nerve.mp3"},"examples":[{"en":"I was going to have a go at parachuting but lost my nerve at the last minute.","cn":"我想尝试一下跳伞，可在最后关头却失去了勇气。"},{"en":"Even after years as a singer, he still suffers from nerves before a performance.","cn":"尽管已做歌手多年，他在演出前仍然神经紧张。"}],"oxford":{"phon":"nɜːv","pos":"noun","senses":[{"en":"any of the long fibres that carry messages between the brain and parts of the body, enabling you to move, feel pain, etc.","cn":"神经","g":"[countable]","ex":{"en":"the optic nerve","cn":"视神经"}},{"en":"feelings of worry or stress","cn":"焦虑；神经紧张","g":"[plural]","ex":{"en":"Even after years as a singer, he still suffers from nerves before a performance.","cn":"尽管已做歌手多年，他在演出前仍然神经紧张。"}},{"en":"the courage to do something difficult or dangerous","cn":"勇气；气魄","g":"[uncountable]","ex":{"en":"It took a lot of nerve to take the company to court.","cn":"将这个公司告上法庭需要极大的勇气。"}},{"en":"a way of behaving that other people think is rude or not appropriate","cn":"鲁莽；冒失；厚颜","g":"[singular, uncountable]","lab":"informal","ex":{"en":"I don't know how you have the nerve to show your face after what you said!","cn":"真不知道你说了那些话以后怎么还有脸露面！"}},{"en":"to give yourself the courage or strength to do something difficult or unpleasant","cn":"鼓足勇气；振作精神","ex":{"en":"He nerved himself to ask her out.","cn":"他鼓足勇气去约她出来。"},"pos":"verb"}]}},"neutralize":{"collins":{"senses":[{"pos":"VERB 动词","cn":"使无效;使无法正常工作","en":"To neutralize something means to prevent it from having any effect or from working properly.","ex":{"en":"The US is trying to neutralize the resolution in the UN Security Council","cn":"美国正试图在联合国安理会使该决议无效。"}},{"pos":"VERB 动词","cn":"(用化学品)中和，使成为中性","en":"When a chemical substance neutralizes an acid, it makes it less acid.","ex":{"en":"Antacids are alkaline and they relieve pain by neutralizing acid in the contents of the stomach.","cn":"抗酸剂是碱性的，通过中和胃容物中的酸来减轻疼痛。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to prevent something from being effective or stop the effect that it was having","cn":""},{"en":"to prevent something from being effective by having an equal but opposite effect","cn":""},{"en":"to prevent something from having any effect","cn":"使失效，抵消"}]},"vocab":{"pos":"v","senses":[{"en":"When you neutralize something, you make it harmless or ineffective — usually by applying its opposite force, like pouring water on a fire."}]},"collocations":{"phrases":["ADV. effectively This strategy effectively neutralized what the Conservatives had hoped would be a vote-winner.","PREP. with Discarded acid should be neutralized with alkali before disposal."]},"media":{"uk":"media/ldoce/hwd/bre/c/neutralize0205.mp3","us":"media/ldoce/hwd/ame/3/laadneutralize.mp3"},"examples":[{"en":"The latest figures should neutralize the fears of inflation.","cn":"最新的数据应该可以消除对通货膨胀的担忧。"},{"en":"Rising prices neutralize increased wages.","cn":"不断上涨的物价会抵消工资的增长。"}],"oxford":{"phon":"ˈnjuːtrəlaɪz","pos":"verb","senses":[{"en":"to stop something from having any effect","cn":"使无效","ex":{"en":"The latest figures should neutralize the fears of inflation.","cn":"最新的数据应该可以消除对通货膨胀的担忧。"}},{"en":"to make a substance neutral","cn":"中和；使成为中性","lab":"chemistry","ex":{"en":"Lime was used to neutralize the acidity of the soil.","cn":"石灰用于中和土壤的酸度。"}},{"en":"to make a country or an area neutral","cn":"使中立","ex":{"en":"The treaty neutralized the Black Sea.","cn":"该条约使黑海地区保持中立。"}}]}},"neurosis":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"神经症","en":"Neurosis is a mental condition which causes people to have unreasonable fears and worries over a long period of time.","ex":{"en":"He was anxious to the point of neurosis","cn":"他焦虑得都要得神经症了。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a mental illness that makes someone unreasonably worried or frightened","cn":"神经症"}]},"vocab":{"pos":"n","senses":[{"en":"If you feel overly anxious and worried, that is a sign of neurosis : a mental illness with no particular cause."}]},"collocations":{"phrases":["ADJ. individual, personal | anxiety, obsessional","VERB + NEUROSIS have","PREP. ~ about the director's neurosis about actors arriving late for filming"]},"media":{"uk":"media/ldoce/hwd/bre/3/neurosis0205.mp3","us":"media/ldoce/hwd/ame/0/ld41neurosis.mp3"},"oxford":{"phon":"njʊəˈrəʊsɪs","pos":"noun","senses":[{"en":"a mental health condition in which a person has strong feelings of fear or worry","cn":"神经症；神经官能症","lab":"psychology","ex":{"en":"She was a psychoanalyst who developed her own theory of neurosis.","cn":"她是一位精神分析师，发展了自己的神经症理论。"}},{"en":"any strong fear or worry","cn":"过分的恐惧（或焦虑）","ex":{"en":"the director's neurosis about actors arriving late for filming","cn":"导演对演员拍片迟到的神经紧张"}}]}},"nepal":{"ldoce":{"phon":"hwd","pos":"","senses":[{"en":"a country in southern Asia, in the Himalayan mountains, north of India and south of China. Population: 30,430,267 (2014). Capital: Kathmandu. Nepal is a place where tourists who want to go walking and climbing in the mountains go.","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/7/p028-000008803.mp3","us":"media/ldoce/hwd/ame/7/p028-000008803.mp3"},"oxford":{"phon":"nəˈpɔːl","pos":"noun","senses":[{"en":"a country in South Asia","cn":"尼泊尔（南亚国家）"}]}},"needy":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"贫苦的;穷困的","en":"Needy people do not have enough food, medicine, or clothing, or adequate houses.","ex":{"en":"...a multinational force aimed at ensuring that food and medicine get to needy Somalis.","cn":"旨在确保将食物和药品送至贫困的索马里民众手中的多国部队"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"having very little money and not many possessions – used about people or places","cn":""},{"en":"having very little money, especially for a short period of time. Skint is more informal than the other words","cn":""},{"en":"a developing country is poor and has very little industry","cn":""}]},"collocations":{"phrases":["VERBS be, look a woman who looked needy","ADV. genuinely, really, truly, very","PHRASES poor and needy helping the children of poor and needy parents"]},"media":{"uk":"media/ldoce/hwd/bre/1/needy0205.mp3","us":"media/ldoce/hwd/ame/b/ld41needy.mp3"},"examples":[{"en":"a needy family","cn":"贫困家庭"},{"en":"money to help the needy","cn":"用来帮助穷人的钱"}],"oxford":{"phon":"ˈniːdi","pos":"adjective","senses":[{"en":"not having enough money, food, clothes, etc.","cn":"缺乏生活必需品的；贫困的"},{"en":"people who do not have enough money, food, etc.","cn":"穷困的人","g":"[plural]","ex":{"en":"help for homeless people and the needy","cn":"帮助无家可归者和有需要的人"}},{"en":"not confident, and needing a lot of love and emotional support from other people","cn":"缺乏自信的；需要精神支持的","ex":{"en":"She is shy and needy.","cn":"她很害羞，也很需要帮助。"}}]}},"nepalese":{"ldoce":{"phon":"hwd","pos":"","senses":[{"en":"a country in southern Asia, in the Himalayan mountains, north of India and south of China. Population: 30,430,267 (2014). Capital: Kathmandu. Nepal is a place where tourists who want to go walking and climbing in the mountains go.","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/7/p028-000008803.mp3","us":"media/ldoce/hwd/ame/7/p028-000008803.mp3"},"oxford":{"phon":"ˌnepəˈliːz","pos":"noun, adjective","senses":[{"en":"(a person) from Nepal","cn":"尼泊尔人；尼泊尔的；尼泊尔人的"}]}},"neighbour":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"邻居;邻人","en":"Your neighbour is someone who lives near you.","ex":{"en":"I got chatting with my neighbour in the garden.","cn":"我在花园里和邻居聊了一会。"}},{"pos":"N-COUNT 可数名词","cn":"邻座;身边的人;邻近的人","en":"You can refer to the person who is standing or sitting next to you as your neighbour .","ex":{"en":"The woman prodded her neighbour and whispered urgently in his ear.","cn":"那位女士捅了捅邻座，急切地在他耳边低语。"}},{"pos":"N-COUNT 可数名词","cn":"邻近的同类物","en":"You can refer to something which stands next to something else of the same kind as its neighbour .","ex":{"en":"Each house was packed close behind its neighbour.","cn":"每幢房子都紧挨着前面的房子而立。"}},{"pos":"N-COUNT 可数名词","cn":"邻国","en":"A country's neighbour is a country that is next to it.","ex":{"en":"...the United States' northern neighbour, Canada.","cn":"美国北部的邻国，加拿大"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who lives next to you or near you","cn":"邻居﹐邻人"},{"en":"a country that is next to another one","cn":"邻国"},{"en":"someone or something that is next to another person or thing of the same type","cn":"身边的人﹔靠近的东西"}]},"collocations":{"phrases":["ADJ. friendly, good She's been a very good neighbour to me. | close, immediate, near, next-door They are near neighbours of ours. | nearest ","PHRASES friends and neighbours"]},"media":{"uk":"media/ldoce/hwd/bre/1/brelasdeneighbour_.mp3","us":"media/ldoce/hwd/ame/2/laadneighbor.mp3"},"examples":[{"en":"The tree fell slowly, its branches caught in those of its neighbours.","cn":"这棵树慢慢地倒下，枝杈和旁边的树交错在一起了。"},{"en":"Stand quietly, children, and try not to talk to your neighbour.","cn":"孩子们，站好，保持安静，不要交头接耳。"}],"oxford":{"phon":"ˈneɪbə(r)","pos":"noun","senses":[{"en":"a person who lives next to you or near you","cn":"邻居；邻人","ex":{"en":"We've had a lot of support from all our friends and neighbours.","cn":"我们的朋友和邻居都很支持我们。"}},{"en":"a country that is next to or near another country","cn":"邻国","ex":{"en":"What is Britain's nearest neighbour?","cn":"英国最近的邻国是哪个国家？"}},{"en":"a person or thing that is standing or located next to another person or thing","cn":"身边的人；靠近的东西；邻近的人（或物）","ex":{"en":"Stand quietly, children, and try not to talk to your neighbour.","cn":"孩子们，站好，保持安静，不要交头接耳。"}},{"en":"any other human","cn":"他人；世人","lab":"literary","ex":{"en":"We should all love our neighbours.","cn":"我们都要爱邻人。"}},{"en":"to be located next to or near to","cn":"与…相邻；邻近","ex":{"en":"The farm neighbours the holiday village.","cn":"农场邻近度假村。"},"pos":"verb"}]}},"nepali":{"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who comes from Nepal","cn":""},{"en":"the language of Nepal","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/6/lpd_nepali.mp3","us":"media/ldoce/hwd/ame/9/nepali_n.mp3"}}});
